/** GIS draw layerCode → mã TS QCVN (`mapAssetIcons`) — SSOT OMS MFE. */
export const ROUTE_LAYER_CODE = 'tuyen-duong';

export function isRouteLayerCode(layerCode: string): boolean {
  return layerCode === ROUTE_LAYER_CODE;
}

export const LAYER_ASSET_CODE: Record<string, string> = {
  'tuyen-duong': 'TD',
  'cot-km': 'KM',
  'bien-bao': 'BB',
  cau: 'CAU',
  ham: 'HAM',
  'ho-lan': 'HL',
  cong: 'CN',
  'ta-luy': 'TL',
  'mat-duong': 'DD',
};

export function layerAssetCode(layerCode: string): string {
  return LAYER_ASSET_CODE[layerCode] || 'TS';
}

export function assetCodeForLayerOrType(code: string): string {
  const fromType = assetCodeForType(code);
  if (fromType !== 'TS') return fromType;
  return layerAssetCode(code);
}

export function itemIsVisible(
  item: GisSavedItem,
  layersVisible: Record<string, boolean>,
  isolatedLayer?: string | null,
): boolean {
  const type = itemTypeCode(item);
  const isRoute = isRouteLayerCode(item.layerCode);
  const vis = isRoute
    ? layersVisible[ROUTE_LAYER_CODE] === true
    : layersVisible[type] === true || layersVisible[item.layerCode] === true;
  if (!vis) return false;
  if (!isolatedLayer) return true;
  if (isolatedLayer === ROUTE_LAYER_CODE) return isRoute;
  return isolatedLayer === type || isolatedLayer === item.layerCode;
}

export function itemTypeCode(item: GisSavedItem): string {
  return String(item.props?.type || item.props?.topType || '').trim().toUpperCase();
}

export function itemAssetCode(item: GisSavedItem): string {
  const fromProp = String(item.props?.assetCode || '').trim().toUpperCase();
  if (fromProp && fromProp !== 'TS') return fromProp;
  const fromType = itemTypeCode(item);
  if (fromType) {
    const mapped = assetCodeForType(fromType);
    if (mapped !== 'TS') return mapped;
  }
  return layerAssetCode(item.layerCode);
}

export function propText(item: GisSavedItem, keys: string[]): string {
  for (const k of keys) {
    const v = item.props?.[k];
    if (v == null) continue;
    const s = String(v).trim();
    if (s) return s;
  }
  return '';
}

function isLayerSlugName(s: string, layerCode: string): boolean {
  const t = s.trim();
  if (!t) return true;
  if (t === layerCode) return true;
  if (LAYER_ASSET_CODE[t]) return true;
  return /^[a-z0-9]+(?:-[a-z0-9]+)+$/.test(t);
}

function isKmChainage(s: string): boolean {
  return /^km\s*[\d]/i.test(s.trim());
}

/** Lý trình 1 cọc (`Km 98`, `Km 12+500`). Cấm đoạn `Km 374 – Km 387` (GAP-DELIM-SPEC-01). */
function isKmPostLabel(s: string): boolean {
  const t = s.trim();
  if (!isKmChainage(t)) return false;
  if (/-.*km\s*[\d]/i.test(t)) return false;
  return true;
}

/** Tên official / catalog — cùng rule popup (cấm slug lớp / Km* làm tên). */
export function inspectDisplayName(item: GisSavedItem): string {
  const type = itemTypeCode(item);
  const assetCode = itemAssetCode(item);
  const catalogName = type ? typeLabel(type) : '';
  const fallbackType = catalogName || assetMeta(assetCode).label;
  const rawName = String(item.name || '').trim();
  const nameIsKm = isKmChainage(rawName);
  const nameIsSlug = isLayerSlugName(rawName, item.layerCode);
  return rawName && !nameIsSlug && !nameIsKm ? rawName : fallbackType;
}

export function inspectKm(item: GisSavedItem): string {
  const rawName = String(item.name || '').trim();
  const kmFrom = propText(item, ['kmFrom', 'km', 'lyTrinh', 'tenCotKm']);
  const kmRaw = kmFrom || (isKmChainage(rawName) ? rawName : '');
  return isKmPostLabel(kmRaw) || /^\d+(\.\d+)?$/.test(kmRaw.trim()) ? kmRaw : '';
}

/** Popup 1 dòng Tuyến — named rồi mã chính. */
export function inspectRoutePopup(item: GisSavedItem): string {
  return propText(item, ['routeNamedName', 'routeNamed', 'routeName', 'route', 'roadCode']);
}

export function itemGps(item: GisSavedItem): { lat: number; lng: number } | null {
  const g = item.geometry;
  if (!g) return null;
  if (g.type === 'Point' && Array.isArray(g.coordinates) && g.coordinates.length >= 2) {
    const lng = Number(g.coordinates[0]);
    const lat = Number(g.coordinates[1]);
    if (Number.isFinite(lat) && Number.isFinite(lng)) return { lat, lng };
  }
  const path = geometryToPath(g);
  if (!path.length) return null;
  const mid = path[Math.floor(path.length / 2)];
  return { lat: mid[0], lng: mid[1] };
}

function statusLabel(raw: string): string {
  const s = raw.trim().toLowerCase();
  if (s === 'can_bao_tri' || s === 'broken' || s === 'high') return 'Cần bảo trì';
  if (s === 'theo_doi' || s === 'medium') return 'Theo dõi';
  if (s === 'tot' || s === 'ok' || s === 'low' || s === '') return 'Đang dùng';
  return raw.trim();
}

/**
 * Popup click tài sản: Tên = catalog gov (`TYPE_LABEL`) khi name = Km* / slug lớp;
 * tên công trình import khi khác lý trình. Không hiện slug `cot-km`.
 */
export function inventoryPopupHtml(
  item: GisSavedItem,
  lat: number,
  lng: number,
  snapped: boolean,
  extra?: string,
): string {
  return buildMapPopupHtml({
    name: inspectDisplayName(item),
    code: item.code || item.id,
    km: inspectKm(item),
    route: inspectRoutePopup(item),
    lat,
    lng,
    assetCode: itemAssetCode(item),
    snapped,
    extra,
  });
}

const SKIP_DUMP_KEYS = new Set(['parentid']);

export function buildGisInspectModel(
  item: GisSavedItem,
  opts?: { snapped?: boolean },
): GisInspectModel {
  const gps = itemGps(item);
  const gpsText =
    gps && Number.isFinite(gps.lat) && Number.isFinite(gps.lng)
      ? `${gps.lat.toFixed(5)}, ${gps.lng.toFixed(5)}`
      : '';
  const type = itemTypeCode(item);
  const typeName = type ? typeLabel(type) : assetMeta(itemAssetCode(item)).label;
  const routeMain = propText(item, ['routeName', 'route', 'roadCode']);
  const routeNamed = propText(item, ['routeNamedName', 'routeNamed']);
  const routeSeg = propText(item, ['routeSegmentName', 'routeSegment']);
  const kmTo = propText(item, ['kmTo']);
  const qty = propText(item, ['quantity']);
  const unit = propText(item, ['unitCode']);
  const note = propText(item, ['note']);
  const status = statusLabel(propText(item, ['status']));

  const rows: GisInspectRow[] = [
    { label: 'Tên:', value: inspectDisplayName(item), name: true },
    { label: 'Mã TS:', value: item.code || item.id },
    { label: 'KM:', value: inspectKm(item) },
    { label: 'GPS:', value: gpsText },
    { label: 'Tuyến:', value: inspectRoutePopup(item) },
    { label: 'Loại:', value: typeName },
    { label: 'Tuyến chính:', value: routeMain },
    { label: 'Tuyến named:', value: routeNamed },
    { label: 'Đoạn:', value: routeSeg },
  ];
  if (kmTo) rows.push({ label: 'KM đến:', value: kmTo });
  if (qty) rows.push({ label: 'Số lượng:', value: unit ? `${qty} ${unit}` : qty });
  if (status) rows.push({ label: 'Trạng thái:', value: status });
  if (note) rows.push({ label: 'Ghi chú:', value: note });

  const specRaw = propText(item, ['dumpSpecs', 'dump_specs']);
  const specRows = parseDumpSpecs(specRaw).filter((r) => !SKIP_DUMP_KEYS.has(r.key.toLowerCase()));
  const specGroups = groupDumpSpecs(type, specRows);

  return { rows, specGroups, snapped: opts?.snapped };
}

/** DB gov-vn `tot` / `theo_doi` / `can_bao_tri` → badge QCVN (R6). */
export function itemUseStatus(item: GisSavedItem): 'ok' | 'broken' {
  const s = String(item.props?.status || item.props?.severity || '').trim().toLowerCase();
  if (s === 'can_bao_tri' || s === 'broken' || s === 'high' || s === 'loi' || s === 'hỏng') {
    return 'broken';
  }
  return 'ok';
}

export const LAYER_COLOR: Record<string, string> = {
  'cot-km': '#7c3aed',
  'bien-bao': '#ea580c',
  'tuyen-duong': OSM_PRIMARY,
  cau: '#0f766e',
  ham: '#1e3a5f',
  'ho-lan': '#dc2626',
  cong: '#0891b2',
  'ta-luy': '#ca8a04',
  'mat-duong': '#334155',
};

const EARTH_M = 6371000;

function asPairs(raw: unknown): [number, number][] {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((pair) => {
      if (!Array.isArray(pair) || pair.length < 2) return null;
      const lng = Number(pair[0]);
      const lat = Number(pair[1]);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
      return [lat, lng] as [number, number];
    })
    .filter((p): p is [number, number] => p != null);
}

export function geometryToPath(geometry: GeoJSON.Geometry | undefined | null): [number, number][] {
  if (!geometry) return [];
  const coords = (geometry as { coordinates?: unknown }).coordinates;
  if (geometry.type === 'Point') {
    if (!Array.isArray(coords) || coords.length < 2) return [];
    const lng = Number(coords[0]);
    const lat = Number(coords[1]);
    return Number.isFinite(lat) && Number.isFinite(lng) ? [[lat, lng]] : [];
  }
  if (geometry.type === 'LineString' || geometry.type === 'MultiPoint') {
    return asPairs(coords);
  }
  if (geometry.type === 'MultiLineString' || geometry.type === 'Polygon') {
    if (!Array.isArray(coords)) return [];
    return coords.flatMap((ring) => asPairs(ring));
  }
  if (geometry.type === 'MultiPolygon') {
    if (!Array.isArray(coords)) return [];
    return coords.flatMap((poly) =>
      Array.isArray(poly) ? poly.flatMap((ring) => asPairs(ring)) : [],
    );
  }
  return [];
}

function haversineM(a: [number, number], b: [number, number]): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(b[0] - a[0]);
  const dLng = toRad(b[1] - a[1]);
  const lat1 = toRad(a[0]);
  const lat2 = toRad(b[0]);
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_M * Math.asin(Math.min(1, Math.sqrt(h)));
}

export function measureGeometry(geometry: GeoJSON.Geometry): { lenM?: number; areaM2?: number } {
  const path = geometryToPath(geometry);
  if (geometry.type === 'LineString' || geometry.type === 'MultiLineString') {
    let len = 0;
    for (let i = 1; i < path.length; i += 1) len += haversineM(path[i - 1], path[i]);
    return { lenM: len };
  }
  if (geometry.type === 'Polygon' || geometry.type === 'MultiPolygon') {
    if (path.length < 3) return {};
    let area = 0;
    for (let i = 0; i < path.length; i += 1) {
      const j = (i + 1) % path.length;
      const xi = ((path[i][1] * Math.PI) / 180) * EARTH_M * Math.cos((path[i][0] * Math.PI) / 180);
      const yi = ((path[i][0] * Math.PI) / 180) * EARTH_M;
      const xj = ((path[j][1] * Math.PI) / 180) * EARTH_M * Math.cos((path[j][0] * Math.PI) / 180);
      const yj = ((path[j][0] * Math.PI) / 180) * EARTH_M;
      area += xi * yj - xj * yi;
    }
    return { areaM2: Math.abs(area / 2) };
  }
  return {};
}

export function drawingToSaved(dto: GisDrawingDto): GisSavedItem {
  const props = { ...(dto.properties || {}) };
  delete props.code;
  delete props.name;
  delete props.status;
  return {
    id: dto.id,
    code: dto.code || String(props.code || ''),
    name: dto.name || String(props.name || ''),
    layerCode: dto.layerCode,
    geometry: dto.geometry,
    props: Object.keys(props).length ? props : undefined,
    at: dto.updatedAt,
  };
}

const LIST_ONLY_LAYERS = new Set(['incidents', 'cameras', 'road_sections', 'all', 'pci_heatmap']);

export function isDbInventoryItem(item: GisSavedItem): boolean {
  const src = String(item.props?.source || '');
  const kind = String(item.props?.sourceKind || '');
  return kind === 'db' || src === 'csv-import' || src === 'gov-vn' || src === 'khu-2-gov';
}

export function isOsrmBakedItem(item: GisSavedItem): boolean {
  return String(item.props?.coordSource || '') === 'osrm-bake';
}

export function seedBakedRoutedLines(
  items: GisSavedItem[],
  prior?: RoutedLinesResult,
): RoutedLinesResult {
  const { byId, byRoute, failed } = cloneRoutedLines(prior);
  const fallback = prior?.fallback ?? false;
  for (const item of items) {
    if (!isOsrmBakedItem(item) || byId.has(item.id) || failed.has(item.id)) continue;
    const path = geometryToPath(item.geometry);
    if (path.length < 2) continue;
    byId.set(item.id, path);
    const key = itemRouteKey(item);
    if (key) appendByRoute(byRoute, key, path, []);
  }
  return { byId, byRoute, failed, fallback, aborted: false };
}

export function normRouteKey(raw: string): string {
  return canonRouteKey(raw);
}

/**
 * Mã tuyến DB: QL.1 ≡ QL.1 - Khánh Hoà ≡ QL1.
 * Khớp BE GisRouteCanon.Canon — cấm lệch key.
 */
export function canonRouteKey(raw: string): string {
  const s = foldRoute(raw);
  if (!s) return '';
  if (s.includes('HOCHIMINH') || s.includes('QLHCM')) return 'QLHCM';
  if (s.includes('TRUONGSONDONG') || (s.includes('TRUONGSON') && s.includes('DONG'))) {
    return 'QLTSDONG';
  }
  const ql = s.match(/QL(\d{1,3})([A-Z])?/);
  if (ql) {
    let suf = ql[2] || '';
    const after = s.slice(ql.index! + ql[0].length);
    if (suf.length === 1 && after.length > 0 && /[A-Z]/.test(after[0])) suf = '';
    return `QL${ql[1]}${suf}`;
  }
  const dt = s.match(/DT(\d{1,3})([A-Z])?/);
  if (dt) {
    let suf = dt[2] || '';
    const after = s.slice(dt.index! + dt[0].length);
    if (suf.length === 1 && after.length > 0 && /[A-Z]/.test(after[0])) suf = '';
    return `DT${dt[1]}${suf}`;
  }
  return s;
}

function foldRoute(raw: string): string {
  return String(raw || '')
    .trim()
    .replace(/[Đđ]/g, 'D')
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '');
}

/** Mã tuyến DB (QL.1 / QL.14D) — không dùng code cột km. */
export function itemRouteKey(item: GisSavedItem): string {
  const route = String(item.props?.route || '').trim();
  if (route) return normRouteKey(route);
  if (isRouteLayerCode(item.layerCode)) {
    return normRouteKey(String(item.code || item.name || ''));
  }
  return '';
}

const OSRM_LINE_CONCURRENCY = 3;

/** Tách LineString nhảy > 150 km trước paint/OSRM — cấm một nét chord cả nước.
 *  `skipSplit`: giữ FeatureId (paint tự tách polyline).
 *  `skipBaked`: chỉ giữ id nét osrm-bake. */
export function expandLineItemsOnJump(
  items: GisSavedItem[],
  opts?: { skipBaked?: boolean; skipSplit?: boolean },
): GisSavedItem[] {
  const out: GisSavedItem[] = [];
  for (const item of items) {
    const isLine =
      item.geometry.type === 'LineString' || item.geometry.type === 'MultiLineString';
    if (!isLine) {
      out.push(item);
      continue;
    }
    if (opts?.skipSplit || (opts?.skipBaked && isOsrmBakedItem(item))) {
      out.push(item);
      continue;
    }
    const segs = splitPathOnJump(geometryToPath(item.geometry));
    if (segs.length === 0) continue;
    segs.forEach((seg, si) => {
      out.push({
        ...item,
        id: segs.length === 1 ? item.id : `${item.id}#${si}`,
        geometry: {
          type: 'LineString',
          coordinates: seg.map(([lat, lng]) => [lng, lat]),
        },
      });
    });
  }
  return out;
}

/** Raw km-chain → byRoute so pin hiện ngay trước OSRM. Fail OSRM không đè seed. */
export function seedCorridorByRoute(items: GisSavedItem[]): Map<string, [number, number][][]> {
  const byRoute = new Map<string, [number, number][][]>();
  for (const item of items) {
    if (!isRouteLayerCode(item.layerCode)) continue;
    const key = itemRouteKey(item);
    const path = geometryToPath(item.geometry);
    if (!key || path.length < 2) continue;
    const segs = byRoute.get(key) || [];
    segs.push(path);
    byRoute.set(key, segs);
  }
  return byRoute;
}

/**
 * OSRM success thay seed — **chỉ** dùng cho visibility (lưới 0.01°).
 * Vị trí pin / popup «snap tim đường» = `osrmPinPlacement` (byRoute OSRM), không seed.
 */
export function mergeRouteCorridors(
  seed: Map<string, [number, number][][]>,
  routed: Map<string, [number, number][][]>,
): Map<string, [number, number][][]> {
  const out = new Map(seed);
  for (const [key, segs] of routed) {
    if (segs.length) out.set(key, segs);
  }
  return out;
}

export type RoutedLinesResult = {
  byId: Map<string, [number, number][]>;
  byRoute: Map<string, [number, number][][]>;
  failed: Set<string>;
  fallback: boolean;
  aborted: boolean;
};

export function emptyRoutedLines(): RoutedLinesResult {
  return {
    byId: new Map(),
    byRoute: new Map(),
    failed: new Set(),
    fallback: false,
    aborted: false,
  };
}

function appendByRoute(
  byRoute: Map<string, [number, number][][]>,
  key: string,
  path: [number, number][],
  refWays: [number, number][][],
) {
  if (!key) return;
  const segs = byRoute.get(key) || [];
  if (refWays.length) segs.push(...refWays);
  else segs.push(path);
  byRoute.set(key, segs);
}

/** Nạp nét đã ghim từ index (memory + IDB) — tick Lớp = show/hide, không OSRM lại. */
export async function hydrateRoutedLinesFromIndex(
  items: GisSavedItem[],
  prior?: RoutedLinesResult,
): Promise<RoutedLinesResult> {
  await ensureOsrmLineIndex();
  const { byId, byRoute, failed } = cloneRoutedLines(prior);
  const fallback = prior?.fallback ?? false;
  for (const item of items) {
    const isLine =
      item.geometry.type === 'LineString' || item.geometry.type === 'MultiLineString';
    if (!isLine) continue;
    const waypoints = geometryToPath(item.geometry);
    if (waypoints.length < 2) continue;
    if (byId.has(item.id) || failed.has(item.id)) continue;
    const rec = lookupOsrmIndexedLine(item.id, lineGeomKey(waypoints));
    if (!rec || rec.path.length < 2) continue;
    byId.set(item.id, rec.path);
    if (isRouteLayerCode(item.layerCode)) {
      appendByRoute(byRoute, itemRouteKey(item) || rec.routeKey, rec.path, rec.refWays || []);
    }
  }
  return { byId, byRoute, failed, fallback, aborted: false };
}

/** z≤8: rút đỉnh km-chain thô. Nét osrm-bake không gọi hàm này. */
export function simplifyPathForLod(
  path: [number, number][],
  lod: 'cluster' | 'corridor' | 'detail',
): [number, number][] {
  if (lod !== 'cluster' || path.length <= 192) return path;
  const step = Math.max(2, Math.ceil(path.length / 64));
  const out: [number, number][] = [path[0]];
  for (let i = step; i < path.length - 1; i += step) out.push(path[i]);
  const last = path[path.length - 1];
  if (out[out.length - 1] !== last) out.push(last);
  return out;
}

function cloneRoutedLines(src?: RoutedLinesResult): RoutedLinesResult {
  if (!src) return emptyRoutedLines();
  const byRoute = new Map<string, [number, number][][]>();
  for (const [k, segs] of src.byRoute) {
    byRoute.set(k, segs.map((s) => s.slice()));
  }
  return {
    byId: new Map(src.byId),
    byRoute,
    failed: new Set(src.failed),
    fallback: src.fallback,
    aborted: false,
  };
}

export async function routeSavedLines(
  items: GisSavedItem[],
  shouldAbort: () => boolean,
  onItem?: (itemId: string, path: [number, number][], snapped: boolean) => void,
  prior?: RoutedLinesResult,
): Promise<RoutedLinesResult> {
  const { byId, byRoute, failed } = cloneRoutedLines(prior);
  let fallback = prior?.fallback ?? false;
  const lines = items.filter((item) => {
    const isLine =
      item.geometry.type === 'LineString' || item.geometry.type === 'MultiLineString';
    return isLine && geometryToPath(item.geometry).length >= 2;
  }).filter((item) => !byId.has(item.id) && !failed.has(item.id));
  for (let i = 0; i < lines.length; i += OSRM_LINE_CONCURRENCY) {
    if (shouldAbort()) {
      break;
    }
    const batch = lines.slice(i, i + OSRM_LINE_CONCURRENCY);
    await Promise.all(
      batch.map(async (item) => {
        if (shouldAbort()) {
          return;
        }
        const waypoints = geometryToPath(item.geometry);
        let path: [number, number][] = [];
        const key = itemRouteKey(item);
        let refWays: [number, number][][] = [];
        let snapped = false;
        try {
          if (isRouteLayerCode(item.layerCode)) {
            const hwy = await routeKmChainAlongHighway(waypoints, key);
            refWays = hwy.refWays;
            if (hwy.path.length >= 2) {
              path = hwy.path;
              snapped = true;
            }
          } else {
            const routed = await routeAlongStreets(waypoints);
            if (routed.length >= 2) {
              path = routed;
              snapped = true;
            }
          }
        } catch {
          snapped = false;
        }
        if (!snapped) {
          fallback = true;
          failed.add(item.id);
          onItem?.(item.id, [], false);
          return;
        }
        byId.set(item.id, path);
        rememberOsrmIndexedLine({
          id: item.id,
          geomKey: lineGeomKey(waypoints),
          path,
          routeKey: key,
          refWays: [],
        });
        onItem?.(item.id, path, true);
        if (!key || !isRouteLayerCode(item.layerCode)) return;
        const segs = byRoute.get(key) || [];
        if (refWays.length) segs.push(...refWays);
        else segs.push(path);
        byRoute.set(key, segs);
      }),
    );
  }
  const incomplete = items.some((item) => {
    const isLine =
      item.geometry.type === 'LineString' || item.geometry.type === 'MultiLineString';
    if (!isLine || geometryToPath(item.geometry).length < 2) return false;
    return !byId.has(item.id) && !failed.has(item.id);
  });
  return { byId, byRoute, failed, fallback, aborted: incomplete };
}

/**
 * Inventory pin: ghim lên corridor **cùng mã tuyến** (`projectToPath`).
 * Caller phải truyền **OSRM byRoute** — cấm seed km-chain (popup «snap» giả).
 * Cùng mã → không giới hạn km (dump lưới / lệch OSM). Thiếu segs → raw.
 * Cấm `{OsrmNearest}` / nearest-mọi-tuyến (snap nhầm QL song song).
 */
export function snapLatLngToCorridors(
  lat: number,
  lng: number,
  routedByRoute?: Map<string, [number, number][][]>,
  preferredRoute?: string,
): [number, number] {
  const key = preferredRoute ? normRouteKey(preferredRoute) : '';
  const segs = key && routedByRoute ? routedByRoute.get(key) : undefined;
  if (!segs?.length) return [lat, lng];
  return projectToNearestPath(lat, lng, segs, Number.POSITIVE_INFINITY);
}

export function snapInventoryPoint(
  item: GisSavedItem,
  pt: [number, number],
  routedByRoute?: Map<string, [number, number][][]>,
): [number, number] {
  return snapLatLngToCorridors(pt[0], pt[1], routedByRoute, itemRouteKey(item));
}

/**
 * Pin trên nét OSRM cùng mã → `snapped: true` (popup «snap tim đường»).
 * Chưa OSRM / fail → raw dump, `snapped: false`. Seed km-chain không đếm là tim đường.
 */
export function osrmPinPlacement(
  raw: [number, number],
  osrmByRoute: Map<string, [number, number][][]> | undefined,
  routeKey: string,
): { ll: [number, number]; snapped: boolean } {
  const key = routeKey ? canonRouteKey(routeKey) : '';
  if (!key || !osrmByRoute?.get(key)?.length) {
    return { ll: raw, snapped: false };
  }
  return { ll: snapLatLngToCorridors(raw[0], raw[1], osrmByRoute, key), snapped: true };
}

/** Lưới Vidagis 0.01° (~1 km) — không phải GPS khảo sát. */
export function isCoarseDegreeGrid(lat: number, lng: number): boolean {
  const coarse = (n: number) => Math.abs(n * 100 - Math.round(n * 100)) < 1e-6;
  return coarse(lat) && coarse(lng);
}

