function edgeLng(lat: number, ring: Array<[number, number]>, pick: 1): number {
  const last = ring[ring.length - 1];
  if (lat >= ring[0][0]) return ring[0][pick];
  if (lat <= last[0]) return last[pick];
  for (let i = 1; i < ring.length; i += 1) {
    const a = ring[i - 1];
    const b = ring[i];
    if (lat <= a[0] && lat >= b[0]) {
      const span = a[0] - b[0];
      const t = span < 1e-9 ? 0 : (a[0] - lat) / span;
      return a[pick] + (b[pick] - a[pick]) * t;
    }
  }
  return ring[0][pick];
}

export function inVietnamMainland(lat: number, lng: number): boolean {
  if (lat < 8.4 || lat > 23.4 || lng < 102.14 || lng > 109.46) return false;
  if (lng >= 109.4 && lat < 13.1) return false;
  const west = edgeLng(lat, VN_WEST, 1);
  const east = edgeLng(lat, VN_EAST, 1);
  return lng + 1e-9 >= west && lng - 1e-9 <= east;
}

/** Bỏ đỉnh ngoài đất liền. <70% trên đất / <2 điểm → không vẽ (cấm chord ra biển). */
export function landReadyPath(path: [number, number][]): [number, number][] | null {
  if (path.length < 2) return null;
  const land = path.filter(([lat, lng]) => inVietnamMainland(lat, lng));
  if (land.length < 2) return null;
  if (land.length < path.length * 0.7) return null;
  return land;
}

export function pathFullyInView(
  path: [number, number][],
  inView: (lat: number, lng: number) => boolean,
): boolean {
  return path.length >= 2 && path.every(([lat, lng]) => inView(lat, lng));
}

/** Giữ đỉnh trong view + 1 đỉnh đệm — SVG ngắn khi tuyến dài cắt viewport. */
export function clipPathToView(
  path: [number, number][],
  inView: (lat: number, lng: number) => boolean,
): [number, number][] {
  if (path.length < 2) return [];
  const keep = path.map((p, i) => {
    if (inView(p[0], p[1])) return true;
    if (i > 0 && inView(path[i - 1][0], path[i - 1][1])) return true;
    if (i < path.length - 1 && inView(path[i + 1][0], path[i + 1][1])) return true;
    return false;
  });
  const out: [number, number][] = [];
  for (let i = 0; i < path.length; i += 1) {
    if (keep[i]) out.push(path[i]);
  }
  return out.length >= 2 ? out : [];
}

/** Survey GPS, hoặc lưới 0.01° đã ghim corridor. Thiếu tuyến / ngoài VN → ẩn, không bịa. */
export function shouldShowInventoryPin(
  raw: [number, number],
  snapped: [number, number] = raw,
  hasRouteCorridor?: boolean,
): boolean {
  if (!inVietnamMainland(snapped[0], snapped[1])) return false;
  if (isCoarseDegreeGrid(raw[0], raw[1]) && !hasRouteCorridor) return false;
  return true;
}

/** Geometry vẽ = path đã OSRM. Fail / pending → path rỗng (caller không addLayer). */
export function snappedLinePath(
  itemId: string,
  waypoints: [number, number][],
  routed: { byId: Map<string, [number, number][]>; failed: Set<string> },
): { path: [number, number][]; snapped: boolean } {
  if (routed.failed.has(itemId)) return { path: waypoints, snapped: false };
  const routedPath = routed.byId.get(itemId);
  if (routedPath && routedPath.length >= 2) return { path: routedPath, snapped: true };
  return { path: [], snapped: false };
}

export type DraftSnapLayer = {
  getLatLng?: () => { lat: number; lng: number };
  setLatLng?: (ll: [number, number]) => void;
  getLatLngs?: () => unknown;
  setLatLngs?: (ll: [number, number][]) => void;
  toGeoJSON?: () => GeoJSON.Feature;
};

function latLngPairsFromDraw(raw: unknown): [number, number][] {
  const flat = (Array.isArray(raw) ? raw : []).flat(2) as Array<{ lat?: number; lng?: number }>;
  return flat
    .map((pt) => {
      const lat = Number(pt?.lat);
      const lng = Number(pt?.lng);
      return Number.isFinite(lat) && Number.isFinite(lng) ? ([lat, lng] as [number, number]) : null;
    })
    .filter((p): p is [number, number] => p != null);
}

/** Draw CREATED: Point → nearest; LineString → match/route. Polygon giữ nguyên. */
export async function snapDraftLayer(layer: DraftSnapLayer | L.Layer): Promise<GeoJSON.Geometry | null> {
  const snap = layer as DraftSnapLayer;
  if (typeof snap.getLatLng === 'function' && typeof snap.setLatLng === 'function') {
    const ll = snap.getLatLng();
    const [la, ln] = await snapPointToStreet(ll.lat, ll.lng);
    snap.setLatLng([la, ln]);
    return snap.toGeoJSON?.()?.geometry ?? null;
  }
  const geom = snap.toGeoJSON?.()?.geometry;
  const geomType = geom?.type;
  if (
    (geomType === 'LineString' || geomType === 'MultiLineString') &&
    typeof snap.getLatLngs === 'function' &&
    typeof snap.setLatLngs === 'function'
  ) {
    const raw = latLngPairsFromDraw(snap.getLatLngs());
    if (raw.length >= 2) {
      const routed = await routeAlongStreets(raw);
      snap.setLatLngs(routed);
      return snap.toGeoJSON?.()?.geometry ?? null;
    }
  }
  return geom ?? null;
}

/** CREATED: snap xong mới trả geometry — cấm addLayer nét thẳng rồi mới setLatLngs. */
export async function snapDraftBeforeShow(
  layer: DraftSnapLayer | L.Layer,
): Promise<{ geometry: GeoJSON.Geometry | null; snapped: boolean }> {
  const raw = (layer as DraftSnapLayer).toGeoJSON?.()?.geometry ?? null;
  try {
    const geometry = await snapDraftLayer(layer);
    return { geometry: geometry ?? raw, snapped: geometry != null };
  } catch {
    return { geometry: raw, snapped: false };
  }
}

export function featureToSaved(feature: GisGeoJsonFeature): GisSavedItem | null {
  const p = (feature.properties || {}) as Record<string, unknown>;
  const geom = feature.geometry;
  if (!geom?.type) return null;
  const rawLayer = String(p.layerCode || p.layer || '');
  const layerCode = LIST_ONLY_LAYERS.has(rawLayer) ? String(p.layerCode || '') : rawLayer;
  if (!layerCode) return null;
  const id = String(feature.id || p.id || '');
  if (!id) return null;
  return {
    id,
    code: String(p.code || ''),
    name: String(p.name || p.title || ''),
    layerCode,
    geometry: geom,
    props: {
      ...p,
      source: p.source,
      sourceKind: p.sourceKind,
    },
    at: new Date().toISOString(),
  };
}

type TaggedLayer = L.Layer & {
  drawingId?: string;
  toGeoJSON?: () => GeoJSON.Feature;
};

type LayerGroupLike = {
  eachLayer?: (fn: (layer: L.Layer) => void) => void;
};

export function tagDrawingLayer(layer: L.Layer, drawingId: string): void {
  (layer as TaggedLayer).drawingId = drawingId;
}

export function drawingIdOf(layer: L.Layer): string | undefined {
  return (layer as TaggedLayer).drawingId;
}

export function geometryOfLayer(layer: L.Layer): GeoJSON.Geometry | null {
  return (layer as TaggedLayer).toGeoJSON?.()?.geometry ?? null;
}

/** Leaflet.Draw Edit/Delete → persist local saved items. */
export function bindDrawEditPersist(
  map: L.Map,
  ctx: {
    savedRef: { current: GisSavedItem[] };
    editSnapshotRef: { current: GisSavedItem[] | null };
    applySaved: (next: GisSavedItem[]) => void;
  },
): void {
  const snapshot = (_e: L.LeafletEvent) => {
    if (!ctx.editSnapshotRef.current) {
      ctx.editSnapshotRef.current = ctx.savedRef.current.map((s) => ({ ...s }));
    }
  };
  map.on('draw:editstart', snapshot);
  map.on('draw:deletestart', snapshot);
  map.on('draw:edited', (e: L.LeafletEvent) => {
    const layers = (e as L.LeafletEvent & { layers?: LayerGroupLike }).layers;
    if (!layers?.eachLayer) return;
    const next = ctx.savedRef.current.slice();
    let changed = false;
    layers.eachLayer((layer) => {
      const id = drawingIdOf(layer);
      const geom = geometryOfLayer(layer);
      if (!id || !geom) return;
      const idx = next.findIndex((s) => s.id === id);
      if (idx < 0) return;
      next[idx] = { ...next[idx], geometry: geom, at: new Date().toISOString() };
      changed = true;
    });
    if (changed) ctx.applySaved(next);
  });
  map.on('draw:deleted', (e: L.LeafletEvent) => {
    const layers = (e as L.LeafletEvent & { layers?: LayerGroupLike }).layers;
    if (!layers?.eachLayer) return;
    const ids = new Set<string>();
    layers.eachLayer((layer) => {
      const id = drawingIdOf(layer);
      if (id) ids.add(id);
    });
    if (!ids.size) return;
    ctx.applySaved(ctx.savedRef.current.filter((s) => !ids.has(s.id)));
  });
}

export function layersFromApi(
  rows: Array<{ value: string; label: string; geomType?: string | null }>,
  fallback: GisLayerDef[],
): GisLayerDef[] {
  if (!rows.length) return fallback;
  return rows.map((r) => ({
    code: r.value,
    name: r.label,
    geom: (r.geomType === 'Polygon' || r.geomType === 'LineString' ? r.geomType : 'Point') as
      | 'Point'
      | 'LineString'
      | 'Polygon',
  }));
}

export function pathToLineString(path: [number, number][]): GeoJSON.Geometry {
  return { type: 'LineString', coordinates: path.map(([lat, lng]) => [lng, lat]) };
}

export function bearingDeg(a: [number, number], b: [number, number]): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const toDeg = (r: number) => (r * 180) / Math.PI;
  const y = Math.sin(toRad(b[1] - a[1])) * Math.cos(toRad(b[0]));
  const x =
    Math.cos(toRad(a[0])) * Math.sin(toRad(b[0])) -
    Math.sin(toRad(a[0])) * Math.cos(toRad(b[0])) * Math.cos(toRad(b[1] - a[1]));
  return (toDeg(Math.atan2(y, x)) + 360) % 360;
}

export function compassLabel(deg: number): string {
  const dirs = ['Bắc', 'Đông Bắc', 'Đông', 'Đông Nam', 'Nam', 'Tây Nam', 'Tây', 'Tây Bắc'];
  return dirs[Math.round(deg / 45) % 8];
}

export function mergeLineGeometries(geoms: GeoJSON.Geometry[]): GeoJSON.Geometry | null {
  const lines: number[][][] = [];
  geoms.forEach((g) => {
    if (g.type === 'LineString' && Array.isArray(g.coordinates)) {
      lines.push(g.coordinates as number[][]);
    }
    if (g.type === 'MultiLineString' && Array.isArray(g.coordinates)) {
      (g.coordinates as number[][][]).forEach((ln) => lines.push(ln));
    }
  });
  if (!lines.length) return null;
  return lines.length === 1
    ? { type: 'LineString', coordinates: lines[0] }
    : { type: 'MultiLineString', coordinates: lines };
}

/** Split a lat/lng path into ~stepM segments (client GIS tool). */
export function splitPathEveryMeters(path: [number, number][], stepM: number): [number, number][][] {
  if (path.length < 2 || stepM <= 0) return path.length ? [path] : [];
  const segs: [number, number][][] = [];
  let cur: [number, number][] = [path[0]];
  let acc = 0;
  for (let i = 1; i < path.length; i += 1) {
    let a = cur[cur.length - 1];
    const b = path[i];
    let rem = haversineM(a, b);
    while (acc + rem >= stepM && rem > 1e-6) {
      const t = (stepM - acc) / rem;
      const p: [number, number] = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
      cur.push(p);
      segs.push(cur);
      cur = [p];
      acc = 0;
      a = p;
      rem = haversineM(a, b);
    }
    cur.push(b);
    acc += rem;
  }
  if (cur.length >= 2) segs.push(cur);
  return segs;
}

type DrawHandler = { enable: () => void; disable: () => void };

function drawToolbarClass(kind: 'marker' | 'polyline' | 'polygon'): string {
  if (kind === 'marker') return 'leaflet-draw-draw-marker';
  if (kind === 'polygon') return 'leaflet-draw-draw-polygon';
  return 'leaflet-draw-draw-polyline';
}

/** Tắt handler đang mở — bấm Hủy trên thanh Leaflet.Draw (Xong / Hoàn tác / Hủy). */
export function disableLeafletDrawUi(map: L.Map): void {
  const cancel = map
    .getContainer?.()
    ?.querySelector('.leaflet-draw-actions li:last-child a') as HTMLElement | null;
  cancel?.click();
}

/**
 * Bật vẽ/đo bằng nút toolbar Leaflet.Draw sẵn có — hiện Xong / Hoàn tác / Hủy.
 * Fallback: `new L.Draw.*` nếu toolbar chưa mount.
 */
export function startLeafletDraw(
  map: L.Map,
  kind: 'marker' | 'polyline' | 'polygon',
  options?: Record<string, unknown>,
): DrawHandler | null {
  const root = map.getContainer?.();
  disableLeafletDrawUi(map);
  const btn = root?.querySelector(`.${drawToolbarClass(kind)}`) as HTMLElement | null;
  if (btn) {
    btn.click();
    return {
      enable: () => btn.click(),
      disable: () => disableLeafletDrawUi(map),
    };
  }
  const DrawNs = (
    window.L as typeof window.L & {
      Draw?: {
        Marker?: new (m: L.Map, o?: Record<string, unknown>) => DrawHandler;
        Polyline?: new (m: L.Map, o?: Record<string, unknown>) => DrawHandler;
        Polygon?: new (m: L.Map, o?: Record<string, unknown>) => DrawHandler;
      };
    }
  ).Draw;
  if (!DrawNs) return null;
  const Ctor =
    kind === 'marker' ? DrawNs.Marker : kind === 'polygon' ? DrawNs.Polygon : DrawNs.Polyline;
  if (!Ctor) return null;
  const clean: Record<string, unknown> = { ...(options || {}) };
  Object.keys(clean).forEach((k) => {
    if (clean[k] === undefined) delete clean[k];
  });
  const handler = new Ctor(map, clean);
  handler.enable();
  return handler;
}
