function inVietnamBbox(lat: number, lng: number): boolean {
  if (lat < 8 || lat > 23.6 || lng < 102 || lng > 109.46) return false;
  const latInt = Math.abs(lat - Math.trunc(lat)) < 1e-9;
  const lngInt = Math.abs(lng - Math.trunc(lng)) < 1e-9;
  if (latInt && lngInt) return false;
  if (lng >= 109.4 && lat < 13.1) return false;
  return true;
}

function pointLatLng(geometry: GeoJSON.Geometry | undefined): [number, number] | null {
  if (!geometry || geometry.type !== 'Point') return null;
  const c = geometry.coordinates;
  if (!Array.isArray(c) || c.length < 2) return null;
  const lng = Number(c[0]);
  const lat = Number(c[1]);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  if (inVietnamBbox(lat, lng)) return [lat, lng];
  if (inVietnamBbox(lng, lat)) return [lng, lat];
  return [lat, lng];
}

/** Cụm: đúng 1 điểm trong nhóm (geometry), không tâm ô lưới. */
function clusterMarkerLatLng(feat: GisGeoJsonFeature): [number, number] | null {
  return pointLatLng(feat.geometry);
}

const GisDrawLivePage: React.FC = () => {
  const { ready, error: leafletError } = useLeaflet();
  const location = useLocation();
  const typeQuery = useMemo(
    () => parseAssetTypeQuery(location.search),
    [location.search],
  );
  const appliedTypeKeyRef = useRef('');
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);
  const drawnRef = useRef<L.FeatureGroup | null>(null);
  const overlayRef = useRef<L.FeatureGroup | null>(null);
  const clusterLayerRef = useRef<L.FeatureGroup | null>(null);
  const pinLayerRef = useRef<L.FeatureGroup | null>(null);
  const pinByIdRef = useRef(new Map<string, L.Layer>());
  const clusterByIdRef = useRef(new Map<string, L.Marker>());
  const routeEndLayerRef = useRef<L.FeatureGroup | null>(null);
  const linePaintSigRef = useRef('');
  const pinPaintSigRef = useRef('');
  const dbItemSigRef = useRef('');
  const lineRoutedRef = useRef<RoutedLinesResult | null>(null);
  const savedRef = useRef<GisSavedItem[]>([]);
  const clipLayerRef = useRef<L.Layer | null>(null);
  const myLocationHoldRef = useRef<MyLocationHold>({ group: null });
  const paintGenRef = useRef(0);
  const inspectItemRef = useRef<(item: GisSavedItem) => void>(() => {});
  const inspectGenRef = useRef(0);
  const isolatedLayerRef = useRef<string | null>(null);
  const clusterFeaturesRef = useRef<GisGeoJsonFeature[]>([]);
  const viewportAbortRef = useRef<AbortController | null>(null);
  const loadViewportRef = useRef<() => Promise<void>>(async () => {});
  const layersVisibleRef = useRef<Record<string, boolean>>({});
  const typePlanCacheRef = useRef<{
    summary: GisTypeSummaryItem[] | null;
    fullByType: Map<string, GisSavedItem[]>;
    corridor: GisSavedItem[] | null;
    corridorBbox: string;
  }>({ summary: null, fullByType: new Map(), corridor: null, corridorBbox: '' });
  const lastBboxRef = useRef('');
  const lastLodRef = useRef<MapLod>('cluster');
  const lastClusterKeyRef = useRef('');
  const viewportGenRef = useRef(0);
  const paintTokenRef = useRef(0);
  const detailByTypeRef = useRef<Map<string, GisSavedItem[]>>(new Map());
  const detailSkipRef = useRef<Map<string, number>>(new Map());
  const detailHasMoreRef = useRef<Map<string, boolean>>(new Map());

  const [catalog, setCatalog] = useState<GisLayerDef[]>([]);
  const [typeCatalogReady, setTypeCatalogReady] = useState(false);
  const [layersVisible, setLayersVisible] = useState<Record<string, boolean>>({});
  const [fetchingLayers, setFetchingLayers] = useState<Set<string>>(() => new Set());
  /** Default dock — parity GIS list */
  const [viewFull, setViewFull] = useState(false);
  const [clipStyle, setClipStyle] = useState<ClipStyleKind>('default');
  const [locating, setLocating] = useState(false);
  const { sideTab, setSideTab, onTabClick, sideBodyOpen, toggleBody, stacked } =
    useGisSideDock();
  const [isolatedId, setIsolatedId] = useState<string | null>(null);
  const [isolatedLayer, setIsolatedLayer] = useState<string | null>(null);
  const [lodMode, setLodMode] = useState<MapLod>('cluster');
  const [mapViewKey, setMapViewKey] = useState('');
  const [clusterFeatures, setClusterFeatures] = useState<GisGeoJsonFeature[]>([]);
  const [typeSummary, setTypeSummary] = useState<GisTypeSummaryItem[]>([]);
  const [, setApiMode] = useState<'bff' | 'local-seed'>('local-seed');
  const [overlayStatus, setOverlayStatus] = useState('idle');
  const [saved, setSaved] = useState<GisSavedItem[]>([]);
  const [selectedItem, setSelectedItem] = useState<GisSavedItem | null>(null);
  const [inspectLoading, setInspectLoading] = useState(false);
  const [inspectSnapped, setInspectSnapped] = useState(false);
  const [, setMsg] = useState('');

  savedRef.current = saved;
  layersVisibleRef.current = layersVisible;
  inspectItemRef.current = (item: GisSavedItem) => {
    inspectGenRef.current += 1;
    const gen = inspectGenRef.current;
    setSelectedItem(item);
    setInspectSnapped(false);
    setSideTab('props');
    if (!isRoadAssetGuid(item.id) || !isDbInventoryItem(item)) {
      setInspectLoading(false);
      return;
    }
    setInspectLoading(true);
    void getRoadAssetDetail(item.id)
      .then((dto) => {
        if (inspectGenRef.current !== gen) return;
        setSelectedItem(mergeRoadAssetDetail(item, dto));
      })
      .catch(() => undefined)
      .finally(() => {
        if (inspectGenRef.current === gen) setInspectLoading(false);
      });
  };

  const layerRows = useMemo<AssetTypeRow[]>(() => {
    if (!typeCatalogReady) return [];
    const fromTypes = catalogFromTypeSummary(
      typeSummary,
      assetMeta,
      assetCodeForType,
      gisTypeLabel,
    );
    const route = catalog.find((l) => l.code === ROUTE_LAYER_CODE);
    if (!route) return fromTypes;
    if (
      fromTypes.some((r) => r.code === ROUTE_LAYER_CODE || r.drawLayer === ROUTE_LAYER_CODE)
    ) {
      return fromTypes;
    }
    return [
      {
        code: route.code,
        name: route.name,
        geom: route.geom,
        assetCode: 'TD',
        count: null,
        drawLayer: route.code,
      },
      ...fromTypes,
    ];
  }, [typeCatalogReady, typeSummary, catalog]);
  const layerRowsRef = useRef(layerRows);
  layerRowsRef.current = layerRows;

  const visibleItems = useMemo(() => {
    return saved.filter((s) => {
      if (!itemIsVisible(s, layersVisible, isolatedLayer)) return false;
      if (isolatedId && s.id !== isolatedId) return false;
      return true;
    });
  }, [saved, layersVisible, isolatedId, isolatedLayer]);

  const isolateTracks = useMemo<IsolateTrack[]>(
    () =>
      saved
        .filter((s) => s.geometry.type === 'LineString' || s.geometry.type === 'MultiLineString')
        .map((s) => ({ id: s.id, code: s.code, path: geometryToPath(s.geometry) })),
    [saved],
  );

  const overviewPath = useMemo(() => {
    const fromItems = visibleItems.flatMap((s) => geometryToPath(s.geometry));
    if (fromItems.length) return fromItems;
    const [[minLat, minLng], [maxLat, maxLng]] = cotKmBoundsLatLng();
    return [
      [minLat, minLng],
      [minLat, maxLng],
      [maxLat, maxLng],
      [maxLat, minLng],
    ] as [number, number][];
  }, [visibleItems]);

  const fitOverview = useCallback(() => {
    const map = mapInstanceRef.current;
    if (!map) return;
    void fitIsolateSelection(map, {
      isolatedId: null,
      tracks: isolateTracks,
      overviewPath,
      delayMs: 40,
    }).then((ok) => {
      if (!ok) {
        try {
          map.fitBounds(cotKmBoundsLatLng(), { padding: [40, 40], maxZoom: 13 });
        } catch {
          fitVnClipMap(map);
        }
      }
    });
  }, [isolateTracks, overviewPath]);

  const loadViewport = useCallback(async () => {
    const map = mapInstanceRef.current;
    if (!map?.getBounds) return;
    const zoom = map.getZoom?.() ?? VN_ZOOM;
    const bbox = boundsToBbox(map.getBounds());
    const lod = lodFromZoom(zoom);
    setLodMode(lod);
    if (lod === 'detail' && clusterFeaturesRef.current.length) {
      clusterFeaturesRef.current = [];
      lastClusterKeyRef.current = '';
      setClusterFeatures([]);
    }
    viewportAbortRef.current?.abort();
    const abort = new AbortController();
    viewportAbortRef.current = abort;
    const gen = ++viewportGenRef.current;
    const isStale = () => abort.signal.aborted || gen !== viewportGenRef.current;
    const isolated = isolatedLayerRef.current;
    const cache = typePlanCacheRef.current;
    const selected = selectedLayerSet(layersVisibleRef.current);
    const paintCorridor =
      selected.has(ROUTE_LAYER_CODE)
      && (!isolated || isolated === ROUTE_LAYER_CODE);
    const wantSnapCorridor = selected.size > 0 && lod !== 'cluster';
    const wantFetchCorridor = paintCorridor || wantSnapCorridor;
    const fetching = new Set<string>();

    const featuresToItems = (features: GisGeoJsonFeature[] | undefined): GisSavedItem[] =>
      (features || [])
        .map(featureToSaved)
        .filter((x): x is GisSavedItem => x != null && isDbInventoryItem(x));

    try {
      if (!cache.summary) {
        setOverlayStatus('summary…');
        const raw = await gisService.getSummaryByType();
        if (isStale()) return;
        const parsed = normalizeTypeSummary(raw);
        cache.summary = parsed.items;
        setTypeSummary(parsed.items);
      }

      const summary = cache.summary || [];
      const fullTypes = filterSelectedTypes(
        typesForMode(summary, 'full', isolated).filter((t) => !isRouteLayerCode(t.layerCode)),
        selected,
      );
      const largeTypes = filterSelectedTypes(
        typesForMode(summary, 'cluster', isolated).filter((t) => !isRouteLayerCode(t.layerCode)),
        selected,
      );

      const viewKey = viewportTileKey(zoom, bbox, lod);
      const sameLod = lod === lastLodRef.current;
      const fetchBbox =
        lod === 'detail' ? padBbox(bbox, VIEWPORT_PAD_RATIO, DETAIL_BBOX_MIN_PAD) : bbox;
      const staleDetail = shouldReloadDetail({
        lastLod: lastLodRef.current,
        lastLoadedBbox: lastBboxRef.current,
        viewBbox: bbox,
      });
      let fetchedCoverage = false;

      const corridorBbox = lod === 'cluster' ? 'national' : padBbox(bbox, 0.45);
      const corridorStale =
        !cache.corridor
        || (lod === 'cluster'
          ? cache.corridorBbox !== 'national'
          : !cache.corridorBbox || !bboxCovers(cache.corridorBbox, bbox));
      const needCorridorFetch = wantFetchCorridor && corridorStale;

      const flattenDetail = () =>
        sortTypesForDetail(largeTypes).flatMap((t) => detailByTypeRef.current.get(t.type) || []);

      const loadDetailChunk = async (types: GisTypeSummaryItem[], budgetLeft: number) => {
        for (const t of types) {
          if (abort.signal.aborted || budgetLeft <= 0) break;
          if (detailHasMoreRef.current.get(t.type) === false) continue;
          const skip = detailSkipRef.current.get(t.type) || 0;
          const take = Math.min(DETAIL_PAGE, budgetLeft);
          const geo = await gisService.getGeoJson(t.type, {
            bbox: fetchBbox,
            lod: 'detail',
            skip,
            take,
          });
          if (isStale()) return;
          const items = featuresToItems(geo.features);
          const prev = detailByTypeRef.current.get(t.type) || [];
          const seen = new Set(prev.map((x) => x.id));
          const merged = prev.slice();
          for (const it of items) {
            if (seen.has(it.id)) continue;
            seen.add(it.id);
            merged.push(it);
          }
          detailByTypeRef.current.set(t.type, merged);
          detailSkipRef.current.set(t.type, skip + items.length);
          const more = geo.hasMore !== false && items.length >= take;
          detailHasMoreRef.current.set(t.type, more);
          budgetLeft -= items.length;
        }
      };

      const selectedKey = [...selected].sort().join(',') || 'none';
      const scale = clusterScale(zoom);
      const clusterKey =
        lod === 'cluster'
          ? `national|${scale}|${isolated || selectedKey}`
          : `${viewKey}|${scale}|${isolated || selectedKey}`;
      const sameClusterKey = clusterKey === lastClusterKeyRef.current;
      const wantClusters =
        largeTypes.length > 0 && (!isolated || isolated !== ROUTE_LAYER_CODE) && !isDetailZoom(zoom);
      const cachedClusters = clusterFeaturesRef.current;
      const canReuseClusters =
        wantClusters
        && !isDetailZoom(zoom)
        && sameLod
        && sameClusterKey
        && cachedClusters.length > 0;
      const needClusters = wantClusters && !canReuseClusters;
      const orderedDetail = sortTypesForDetail(largeTypes);
      const needDetail =
        isDetailZoom(zoom)
        && largeTypes.length > 0
        && (!isolated || isolated !== ROUTE_LAYER_CODE)
        && flattenDetail().length < DETAIL_PIN_BUDGET
        && (staleDetail || orderedDetail.some((t) => detailHasMoreRef.current.get(t.type) !== false));

      if (needCorridorFetch) fetching.add(ROUTE_LAYER_CODE);
      for (const t of fullTypes) {
        if (!cache.fullByType.has(t.type)) fetching.add(t.type);
      }
      if (needClusters || needDetail) {
        largeTypes.forEach((t) => fetching.add(t.type));
      }
      setFetchingLayers(new Set(fetching));

      const firstJobs: Promise<void>[] = [];

      for (const t of fullTypes) {
        if (cache.fullByType.has(t.type)) continue;
        firstJobs.push(
          (async () => {
            const geo = await gisService.loadGeoJsonBatched(
              t.type,
              { lod: 'full' },
              { signal: abort.signal },
            );
            if (isStale()) return;
            cache.fullByType.set(t.type, featuresToItems(geo.features));
          })(),
        );
      }

      let nextClusters: GisGeoJsonFeature[] = canReuseClusters ? cachedClusters.slice() : [];
      let detailItems: GisSavedItem[] = [];

      if (!largeTypes.length || (isolated && isolated === ROUTE_LAYER_CODE)) {
        nextClusters = [];
      } else if (isDetailZoom(zoom)) {
        nextClusters = [];
        if (staleDetail) {
          detailSkipRef.current = new Map();
          detailHasMoreRef.current = new Map();
        }
      } else {
        detailByTypeRef.current = new Map();
        detailSkipRef.current = new Map();
        detailHasMoreRef.current = new Map();
        if (needClusters) {
          firstJobs.push(
            (async () => {
              setOverlayStatus('cụm vùng…');
              const layers = isolated
                ? [isolated]
                : [...new Set(largeTypes.map((t) => t.type).filter(Boolean))];
              const fcs = await Promise.all(
                layers.map((layer) =>
                  getGisClusters({
                    zoom,
                    layer,
                    ...(lod === 'cluster' ? {} : { bbox }),
                  }),
                ),
              );
              if (isStale()) return;
              const seen = new Set<string>();
              const merged: GisGeoJsonFeature[] = [];
              for (const fc of fcs) {
                for (const feat of fc.features || []) {
                  const id = String(feat.id || feat.properties?.id || '');
                  if (id && seen.has(id)) continue;
                  if (id) seen.add(id);
                  merged.push(feat);
                }
              }
              nextClusters = merged;
              fetchedCoverage = true;
            })(),
          );
        }
      }

      await Promise.all(firstJobs);
      if (isStale()) return;

      if (needCorridorFetch) {
        setOverlayStatus('tuyến…');
        const geo = await gisService.getGeoJson(ROUTE_LAYER_CODE, {
          lod: 'corridor',
          ...(lod === 'cluster' ? {} : { bbox: corridorBbox }),
          take: CORRIDOR_ROUTE_TAKE,
        });
        if (isStale()) return;
        cache.corridor = featuresToItems(geo.features);
        cache.corridorBbox = corridorBbox;
        linePaintSigRef.current = '';
      }

      if (isDetailZoom(zoom) && largeTypes.length && (!isolated || isolated !== ROUTE_LAYER_CODE)) {
        if (needDetail) {
          fetchedCoverage = true;
          setOverlayStatus(flattenDetail().length ? 'tải thêm pin…' : 'chi tiết vùng…');
          const wave1 = orderedDetail.slice(0, 5);
          const wave2 = orderedDetail.slice(5);
          await loadDetailChunk(wave1, DETAIL_PIN_BUDGET - flattenDetail().length);
          if (isStale()) return;
          detailItems = flattenDetail();
          const fullItemsEarly = fullTypes.flatMap((t) => cache.fullByType.get(t.type) || []);
          const corridorEarly = wantFetchCorridor ? cache.corridor || [] : [];
          const earlyDb = [...corridorEarly, ...fullItemsEarly, ...detailItems];
          const earlySig = earlyDb.map((x) => x.id).join('|');
          if (earlySig !== dbItemSigRef.current) {
            dbItemSigRef.current = earlySig;
            setSaved((prev) => {
              const local = prev.filter((s) => !isDbInventoryItem(s));
              return [...local, ...earlyDb];
            });
          }
          await loadDetailChunk(wave2, DETAIL_PIN_BUDGET - flattenDetail().length);
          if (isStale()) return;
          while (flattenDetail().length < DETAIL_PIN_BUDGET && !isStale()) {
            const moreTypes = orderedDetail.filter(
              (t) => detailHasMoreRef.current.get(t.type) !== false,
            );
            if (!moreTypes.length) break;
            const before = flattenDetail().length;
            await loadDetailChunk(moreTypes, DETAIL_PIN_BUDGET - before);
            if (flattenDetail().length === before) break;
          }
        }
        detailItems = flattenDetail();
        nextClusters = [];
      }

      if (isStale()) return;

      const fullItems = fullTypes.flatMap((t) => cache.fullByType.get(t.type) || []);
      const corridorItems = wantFetchCorridor ? cache.corridor || [] : [];
      const dbItems = [...corridorItems, ...fullItems, ...detailItems];
      const dbSig = dbItems.map((x) => x.id).join('|');

      lastLodRef.current = lod;
      if (fetchedCoverage) {
        lastBboxRef.current = lod === 'detail' ? fetchBbox : bbox;
      }

      clusterFeaturesRef.current = nextClusters;
      lastClusterKeyRef.current = nextClusters.length > 0 ? clusterKey : '';
      setClusterFeatures(nextClusters);
      if (dbSig !== dbItemSigRef.current) {
        dbItemSigRef.current = dbSig;
        setSaved((prev) => {
          const local = prev.filter((s) => !isDbInventoryItem(s));
          return [...local, ...dbItems];
        });
      }
      setApiMode('bff');
      const morePin =
        isDetailZoom(zoom)
        && sortTypesForDetail(largeTypes).some((t) => detailHasMoreRef.current.get(t.type) !== false);
      setMsg(
        isDetailZoom(zoom)
          ? `Tuyến ${paintCorridor ? corridorItems.length : 0} · đủ ${fullItems.length} · pin ${detailItems.length}${morePin ? ' · còn tải' : ''}`
          : `Tuyến ${paintCorridor ? corridorItems.length : 0} · đủ ${fullItems.length} · ${nextClusters.length} cụm vùng`,
      );
    } catch {
      if (!isStale()) {
        setApiMode('local-seed');
        setMsg('BFF/API chưa sẵn — fallback local');
      }
    } finally {
      if (!isStale()) setFetchingLayers(new Set());
    }
  }, []);

  loadViewportRef.current = loadViewport;
  isolatedLayerRef.current = isolatedLayer;
  clusterFeaturesRef.current = clusterFeatures;

  const loadSavedOntoMap = useCallback(async () => {
    const L = window.L;
    const map = mapInstanceRef.current;
    const drawn = drawnRef.current;
    if (!L || !map || !drawn) return;

    try {
      const myPaint = ++paintTokenRef.current;
      ensureLinePanes(map);
      ensureAssetIconStyles();
      const pinInView = (lat: number, lng: number): boolean => {
        const bounds = map.getBounds?.();
        if (!bounds) return true;
        const minPad = lodMode === 'detail' ? DETAIL_PIN_PAD_DEG : 0.002;
        const ratio = lodMode === 'detail' ? 0.5 : 0.18;
        return latLngInPaddedBounds(lat, lng, bounds, ratio, minPad);
      };
      const visClusters =
        lodMode === 'detail'
          ? []
          : clusterFeatures.filter((feat) => {
        const lc = String(feat.properties?.layerCode || '');
        const topType = String(
          feat.properties?.topType || feat.properties?.type || '',
        )
          .trim()
          .toUpperCase();
        if (isRouteLayerCode(lc)) return false;
        const vis =
          layersVisible[topType] === true
          || layersVisible[lc] === true
          || layersVisible[lc.toUpperCase()] === true;
        if (!vis) return false;
        if (
          isolatedLayer
          && isolatedLayer !== topType
          && isolatedLayer !== lc
        ) {
          return false;
        }
        return true;
      });

      const emptyByRoute = new Map<string, [number, number][][]>();
      const syncClusterMarkers = (
        osrmByRoute: Map<string, [number, number][][]>,
        seedByRoute: Map<string, [number, number][][]>,
      ) => {
        if (myPaint !== paintTokenRef.current) return;
        const clusterGroup = clusterLayerRef.current;
        const wantedClusters = new Set<string>();
        for (const feat of visClusters) {
          const raw = clusterMarkerLatLng(feat);
          if (!raw) continue;
          const cid = String(feat.id || feat.properties?.id || '');
          if (!cid) continue;
          const props = feat.properties || {};
          const routeKey = String(props.route || '');
          const placed =
            lodMode === 'cluster'
              ? { ll: raw, snapped: false }
              : osrmPinPlacement(raw, osrmByRoute, routeKey);
          const ll = placed.ll;
          if (!inVietnamMainland(ll[0], ll[1])) continue;
          if (
            lodMode !== 'cluster'
            && isCoarseDegreeGrid(raw[0], raw[1])
            && !placed.snapped
          ) {
            continue;
          }
          if (
            lodMode !== 'cluster'
            && !pinInView(ll[0], ll[1])
            && !pinInView(raw[0], raw[1])
          ) {
            continue;
          }
          if (lodMode !== 'cluster') {
            const key = canonRouteKey(routeKey);
            const hasCorridor = Boolean(
              key && (osrmByRoute.get(key)?.length || seedByRoute.get(key)?.length),
            );
            if (!shouldShowInventoryPin(raw, ll, hasCorridor)) continue;
          }
          wantedClusters.add(cid);
          const existing = clusterByIdRef.current.get(cid);
          const clusterPopup = buildMapPopupHtml({
            name: gisTypeLabel(String(props.topType || '')) || assetMeta(String(props.assetCode || 'TS')).label,
            code: String(props.sampleCode || props.code || cid),
            km: '',
            route: routeKey,
            lat: ll[0],
            lng: ll[1],
            assetCode: String(props.assetCode || 'TS'),
            snapped: placed.snapped,
            extra: `${formatAssetCount(Number(props.count) || 0)} tài sản`,
          });
          if (existing) {
            existing.setLatLng(ll);
            bindAssetPopup(existing, clusterPopup, L);
            continue;
          }
          const count = Number(props.count) || 0;
          const assetCode = String(props.assetCode || 'TS');
          const icon = createClusterLeafletIcon(L, count, assetCode);
          if (!icon) continue;
          const typeLabel = gisTypeLabel(String(props.topType || '')) || assetMeta(assetCode).label;
          const sample = String(props.sampleCode || props.code || '');
          const marker = L.marker(ll, {
            icon,
            ...ASSET_DISPLAY_MARKER_OPTS,
            zIndexOffset: 800,
            title: `${typeLabel} · ${formatAssetCount(count)} · ${sample}`,
          });
          bindAssetPopup(marker, clusterPopup, L);
          marker.on?.('click', () => {
            const z = map.getZoom?.() ?? 0;
            if (z < DETAIL_ZOOM) {
              map.setView(ll, DETAIL_ZOOM);
            }
          });
          clusterGroup?.addLayer(marker);
          clusterByIdRef.current.set(cid, marker);
        }
        for (const [id, marker] of [...clusterByIdRef.current]) {
          if (wantedClusters.has(id)) continue;
          try {
            clusterGroup?.removeLayer(marker);
          } catch {
            /* gone */
          }
          clusterByIdRef.current.delete(id);
        }
      };
      const selected = selectedLayerSet(layersVisible);
      const drawRouteLines =
        selected.has(ROUTE_LAYER_CODE)
        && (!isolatedLayer || isolatedLayer === ROUTE_LAYER_CODE);
      const osrmPins = lodMode !== 'cluster';
      const hiddenCorridor =
        osrmPins && selected.size > 0 && !selected.has(ROUTE_LAYER_CODE)
          ? savedRef.current.filter(
              (s) => isDbInventoryItem(s) && isRouteLayerCode(s.layerCode),
            )
          : [];
      const pathHitsView = (item: GisSavedItem): boolean => {
        const p = geometryToPath(item.geometry);
        if (p.length < 2) return false;
        return p.some(([lat, lng]) => pinInView(lat, lng));
      };
      const viewRank = (item: GisSavedItem): number => {
        const p = geometryToPath(item.geometry);
        if (pathFullyInView(p, pinInView)) return 0;
        if (pathHitsView(item)) return 1;
        return 2;
      };
      const byViewThenLen = (a: GisSavedItem, b: GisSavedItem) => {
        const d = viewRank(a) - viewRank(b);
        if (d !== 0) return d;
        const la = geometryToPath(a.geometry).length;
        const lb = geometryToPath(b.geometry).length;
        if (lodMode === 'cluster') return lb - la;
        return la - lb;
      };
      const visiblePaint = expandLineItemsOnJump(visibleItems, { skipSplit: true });
      const pendingPoints: GisSavedItem[] = [];
      const pendingPolys: GisSavedItem[] = [];
      const lineCandidates: GisSavedItem[] = [];
      for (const item of visiblePaint) {
        if (isRouteLayerCode(item.layerCode) && item.geometry.type === 'Point') {
          continue;
        }
        if (item.geometry.type === 'Point') {
          pendingPoints.push(item);
          continue;
        }
        const isLine =
          item.geometry.type === 'LineString' || item.geometry.type === 'MultiLineString';
        if (isLine && geometryToPath(item.geometry).length >= 2) {
          const wantLine = isRouteLayerCode(item.layerCode) ? drawRouteLines : osrmPins;
          if (
            wantLine
            && (isOsrmBakedItem(item) || pathHitsView(item))
          ) {
            lineCandidates.push(item);
          }
          continue;
        }
        if (!isLine) pendingPolys.push(item);
      }
      lineCandidates.sort(byViewThenLen);

      const pinRouteKeys = new Set<string>();
      for (const item of pendingPoints) {
        const k = itemRouteKey(item);
        if (k) pinRouteKeys.add(k);
      }
      for (const feat of visClusters) {
        const k = canonRouteKey(String(feat.properties?.route || ''));
        if (k) pinRouteKeys.add(k);
      }
      const osrmCandidates = expandLineItemsOnJump([...visibleItems, ...hiddenCorridor]).filter(
        pathHitsView,
      );
      const liveOsrm = lodMode !== 'cluster';
      let routed: RoutedLinesResult = seedBakedRoutedLines(
        expandLineItemsOnJump([...visiblePaint, ...hiddenCorridor], { skipSplit: true }),
        lineRoutedRef.current || emptyRoutedLines(),
      );
      routed = await hydrateRoutedLinesFromIndex(
        expandLineItemsOnJump([...visiblePaint, ...hiddenCorridor], { skipSplit: true }),
        routed,
      );
      if (myPaint !== paintTokenRef.current) return;
      lineRoutedRef.current = routed;

      const indexedCandidates = lineCandidates.filter((s) => routed.byId.has(s.id));
      const missingCandidates = liveOsrm
        ? osrmCandidates
            .filter((s) => !routed.byId.has(s.id) && !routed.failed.has(s.id))
            .slice()
            .sort((a, b) => {
              const pinA = pinRouteKeys.has(itemRouteKey(a)) ? 0 : 1;
              const pinB = pinRouteKeys.has(itemRouteKey(b)) ? 0 : 1;
              if (pinA !== pinB) return pinA - pinB;
              return byViewThenLen(a, b);
            })
        : [];
      const osrmPaint = missingCandidates.slice(0, OSRM_VIEWPORT_MAX);
      const bakedItems = lineCandidates.filter(isOsrmBakedItem);
      const indexedRest = indexedCandidates.filter((s) => !isOsrmBakedItem(s));
      const lineItems: GisSavedItem[] =
        lodMode === 'cluster'
          ? [...bakedItems, ...indexedRest].slice(0, CORRIDOR_ROUTE_TAKE)
          : [
              ...indexedCandidates,
              ...osrmPaint.filter((s) => !indexedCandidates.some((x) => x.id === s.id)),
            ];
      const seededByRoute = seedCorridorByRoute(
        expandLineItemsOnJump(
          [
            ...hiddenCorridor,
            ...visiblePaint.filter((s) => isRouteLayerCode(s.layerCode)),
          ],
          { skipSplit: true },
        ),
      );

      const pins = pinLayerRef.current;
      const syncPins = (osrmByRoute: Map<string, [number, number][][]>) => {
        if (myPaint !== paintTokenRef.current) return;
        const wantedPins = new Set<string>();
        for (const item of pendingPoints) {
          const assetCode = itemAssetCode(item);
          const useStatus = itemUseStatus(item);
          const pt = geometryToPath(item.geometry)[0];
          if (!pt) continue;
          const key = itemRouteKey(item);
          const { ll: latlng, snapped } = osrmPinPlacement(pt, osrmByRoute, key);
          if (!pinInView(latlng[0], latlng[1]) && !pinInView(pt[0], pt[1])) continue;
          if (lodMode !== 'cluster' && isCoarseDegreeGrid(pt[0], pt[1]) && !snapped) continue;
          const hasCorridor = Boolean(
            key && (osrmByRoute.get(key)?.length || seededByRoute.get(key)?.length),
          );
          if (!shouldShowInventoryPin(pt, latlng, hasCorridor)) continue;
          wantedPins.add(item.id);
          const popupHtml = inventoryPopupHtml(item, latlng[0], latlng[1], snapped);
          const existing = pinByIdRef.current.get(item.id) as L.Marker | undefined;
          if (existing?.setLatLng) {
            existing.setLatLng(latlng);
            bindAssetPopup(existing, popupHtml, L);
            continue;
          }
          const icon = createAssetLeafletIcon(L, assetCode, useStatus);
          const marker = L.marker(latlng, {
            ...(icon ? { icon } : {}),
            ...ASSET_DISPLAY_MARKER_OPTS,
            title: `${item.code || item.name} · ${assetCode}`,
            zIndexOffset: 1200,
            riseOnHover: true,
          });
          bindAssetPopup(marker, popupHtml, L);
          marker.on?.('click', () => {
            try {
              inspectItemRef.current(item);
            } catch {
              /* layer torn down */
            }
          });
          tagDrawingLayer(marker, item.id);
          pins?.addLayer(marker);
          pinByIdRef.current.set(item.id, marker);
        }
        for (const item of pendingPolys) {
          const polyPath = geometryToPath(item.geometry);
          const polyMid = polyPath[0];
          if (polyMid && !pinInView(polyMid[0], polyMid[1])) continue;
          wantedPins.add(item.id);
          if (pinByIdRef.current.has(item.id)) continue;
          const color = LAYER_COLOR[item.layerCode] || '#2563eb';
          const mid = polyMid || [VN_CENTER[0], VN_CENTER[1]];
          const polyPopup = inventoryPopupHtml(item, mid[0], mid[1], false);
          const gj = L.geoJSON(item.geometry, {
            style: () => ({
              color,
              weight: 3,
              fillOpacity: 0.22,
              pane: 'rmms-zone',
            }),
            onEachFeature: (_feat, layer) => {
              bindAssetPopup(layer as L.Path, polyPopup, L);
            },
          });
          const addPoly = (layer: L.Layer) => {
            tagDrawingLayer(layer, item.id);
            layer.on?.('click', () => {
              try {
                inspectItemRef.current(item);
              } catch {
                /* ignore */
              }
            });
            pins?.addLayer(layer);
            pinByIdRef.current.set(item.id, layer);
          };
          if (gj.eachLayer) gj.eachLayer(addPoly);
          else addPoly(gj);
        }
        for (const [id, layer] of [...pinByIdRef.current]) {
          if (wantedPins.has(id)) continue;
          try {
            pins?.removeLayer(layer);
          } catch {
            /* gone */
          }
          pinByIdRef.current.delete(id);
        }
        pinPaintSigRef.current = pinSig;
      };

      const lineSig = lineItems
        .map((x) => {
          const p = geometryToPath(x.geometry);
          const a = p[0];
          return `${x.id}:${p.length}:${a ? a[0].toFixed(3) : ''}:${a ? a[1].toFixed(3) : ''}`;
        })
        .join('|');
      const pinSig = [...pendingPoints, ...pendingPolys].map((x) => x.id).join('|');
      syncClusterMarkers(lineRoutedRef.current?.byRoute || emptyByRoute, seededByRoute);
      syncPins(lineRoutedRef.current?.byRoute || emptyByRoute);

      const removeLineById = (id: string) => {
        const visit = (layer: L.Layer) => {
          if (drawingIdOf(layer) !== id) return;
          try {
            overlayRef.current?.removeLayer(layer);
          } catch {
            /* gone */
          }
          try {
            drawn.removeLayer(layer);
          } catch {
            /* gone */
          }
        };
        overlayRef.current?.eachLayer(visit);
        drawn.eachLayer(visit);
      };

      const paintSnappedLine = (item: GisSavedItem, path: [number, number][]) => {
        const baked = isOsrmBakedItem(item);
        const clipped =
          lodMode === 'cluster' || baked ? path : clipPathToView(path, pinInView);
        const forLod =
          baked || lodMode === 'cluster'
            ? clipped.length
              ? clipped
              : path
            : simplifyPathForLod(clipped.length ? clipped : path, lodMode);
        const ready =
          baked || lodMode === 'cluster' ? forLod : landReadyPath(forLod);
        if (!ready || ready.length < 2) {
          removeLineById(item.id);
          return;
        }
        const segs = splitPathOnJump(ready);
        if (segs.length === 0) {
          removeLineById(item.id);
          return;
        }
        removeLineById(item.id);
        const isRoute = isRouteLayerCode(item.layerCode);
        const pair = isRoute ? cartoRoutePairStyle() : null;
        const style = pair
          ? pair.fill
          : {
              ...trackLineStyle(LAYER_COLOR[item.layerCode] || '#2563eb', { weight: 4 }),
              pane: 'overlayPane',
            };
        for (const seg of segs) {
          if (pair) {
            const casing = L.polyline(seg, pair.casing);
            tagDrawingLayer(casing, item.id);
            if (isDbInventoryItem(item)) overlayRef.current?.addLayer(casing);
            else drawn.addLayer(casing);
          }
          const track = L.polyline(seg, style);
          tagDrawingLayer(track, item.id);
          if (isDbInventoryItem(item)) overlayRef.current?.addLayer(track);
          else drawn.addLayer(track);
          const mid = seg[Math.floor(seg.length / 2)] || seg[0];
          bindAssetPopup(track, inventoryPopupHtml(item, mid[0], mid[1], true), L);
          track.on?.('click', () => {
            inspectItemRef.current(item);
          });
        }
      };

      const applyLineGeometry = (
        id: string,
        path: [number, number][],
        snapped: boolean,
      ) => {
        if (!snapped || path.length < 2) {
          removeLineById(id);
          return;
        }
        const item = lineItems.find((x) => x.id === id);
        if (!item) {
          removeLineById(id);
          return;
        }
        paintSnappedLine(item, path);
      };

      const applyRoutedLatLngs = (routedNow: {
        byId: Map<string, [number, number][]>;
        failed: Set<string>;
        fallback: boolean;
      }): boolean => {
        let fallback = routedNow.fallback;
        const wanted = new Set(lineItems.map((x) => x.id));
        for (const item of lineItems) {
          const waypoints = geometryToPath(item.geometry);
          const { path, snapped } = snappedLinePath(item.id, waypoints, routedNow);
          if (!snapped) {
            fallback = true;
            removeLineById(item.id);
            continue;
          }
          paintSnappedLine(item, path);
        }
        const extraIds: string[] = [];
        overlayRef.current?.eachLayer((layer) => {
          const id = drawingIdOf(layer);
          if (id && !wanted.has(id)) extraIds.push(id);
        });
        extraIds.forEach(removeLineById);
        return fallback;
      };

      if (lodMode === 'cluster' && !drawRouteLines) {
        overlayRef.current?.clearLayers();
        linePaintSigRef.current = '';
      } else {
        linePaintSigRef.current = lineSig;
      }

      let osrmFallback = routed.fallback;

      if (drawRouteLines || osrmPins) {
        osrmFallback = applyRoutedLatLngs(routed);
        const unfinished = liveOsrm && osrmPaint.some(
          (s) => !routed.byId.has(s.id) && !routed.failed.has(s.id),
        );
        if (unfinished) {
          setOverlayStatus('tim đường…');
          const next = await routeSavedLines(
            osrmPaint,
            () => myPaint !== paintTokenRef.current,
            (id, path, snapped) => {
              if (myPaint !== paintTokenRef.current) return;
              applyLineGeometry(id, path, snapped);
            },
            routed,
          );
          if (myPaint === paintTokenRef.current) {
            routed = next;
            lineRoutedRef.current = routed;
            osrmFallback = applyRoutedLatLngs(routed);
          }
        }
      }

      if (myPaint !== paintTokenRef.current) return;
      syncClusterMarkers(routed.byRoute, seededByRoute);
      syncPins(routed.byRoute);

      routeEndLayerRef.current?.clearLayers();
      if (osrmPins && lineItems.some((s) => isRouteLayerCode(s.layerCode))) {
        const ends = routeEndLayerRef.current;
        const tdIcon = createAssetLeafletIcon(L, 'TD');
        for (const item of lineItems) {
          if (myPaint !== paintTokenRef.current) return;
          if (!isRouteLayerCode(item.layerCode)) continue;
          const waypoints = geometryToPath(item.geometry);
          const { path, snapped } = snappedLinePath(item.id, waypoints, routed);
          const ready = snapped ? landReadyPath(path) : null;
          if (!ready) continue;
          const pair: Array<{ ll: [number, number]; label: string }> = [
            { ll: ready[0], label: 'Đầu tuyến' },
            { ll: ready[ready.length - 1], label: 'Cuối tuyến' },
          ];
          for (const ep of pair) {
            const marker = L.marker(ep.ll, {
              ...(tdIcon ? { icon: tdIcon } : {}),
              ...ASSET_DISPLAY_MARKER_OPTS,
              zIndexOffset: 1400,
              title: `${ep.label} · ${item.name || item.code}`,
            });
            bindAssetPopup(
              marker,
              inventoryPopupHtml(item, ep.ll[0], ep.ll[1], snapped, ep.label),
              L,
            );
            marker.on?.('click', () => {
              inspectItemRef.current(item);
            });
            ends?.addLayer(marker);
          }
        }
      }

      if (myPaint !== paintTokenRef.current) return;
      const snappedInView = lineItems.filter((s) => routed.byId.has(s.id)).length;
      setOverlayStatus(
        isolatedId
          ? `isolate · ${isolatedId}`
          : routed.aborted && liveOsrm
            ? `tim đường · ${snappedInView}/${Math.max(osrmPaint.length, lineItems.length)}`
          : lodMode === 'cluster' && drawRouteLines && snappedInView === 0
            ? 'đang bake tuyến (OSRM)…'
          : lodMode === 'cluster' && lineItems.length
            ? `tuyến · ${snappedInView} đã ghim`
          : snappedInView === 0 && lineItems.length
            ? osrmFallback
              ? 'OSRM fallback · ẩn nét'
              : 'OSRM chưa ghim · ẩn nét'
          : lineItems.length
            ? `tuyến · ${snappedInView} đã ghim`
            : visClusters.length
              ? `cụm · ${visClusters.length}`
              : 'sẵn',
      );
    } catch (err) {
      setOverlayStatus(err instanceof Error ? err.message : 'Không vẽ được lớp bản đồ');
    }
  }, [visibleItems, isolatedId, isolatedLayer, clusterFeatures, layersVisible, lodMode, mapViewKey]);

  useEffect(() => {
    if (!ready || !mapRef.current) return;
    const L = window.L;
    if (!L?.map) return;
    const el = mapRef.current;

    if (mapInstanceRef.current) {
      try {
        mapInstanceRef.current.remove();
      } catch {
        /* HMR leftover */
      }
      mapInstanceRef.current = null;
    }
    resetLeafletContainer(el);
    ensureAssetIconStyles();

    let map: L.Map;
    try {
      map = L.map(el, vnLeafletMapOptions({ center: VN_CENTER, zoom: VN_CLIP_MIN_ZOOM }));
    } catch {
      resetLeafletContainer(el);
      try {
        map = L.map(el, vnLeafletMapOptions({ center: VN_CENTER, zoom: VN_CLIP_MIN_ZOOM }));
      } catch (err2) {
        setOverlayStatus(err2 instanceof Error ? err2.message : 'Không tạo được bản đồ');
        return undefined;
      }
    }

    try {
      clipLayerRef.current = attachVnClipBasemap(map, clipStyle);
    } catch (clipErr) {
      setOverlayStatus(
        clipErr instanceof Error ? clipErr.message : 'Không gắn nền clip BFF',
      );
      return undefined;
    }
    ensureLinePanes(map);
    const overlay = new L.FeatureGroup().addTo(map);
    const clusterLayer = new L.FeatureGroup().addTo(map);
    const pinLayer = new L.FeatureGroup().addTo(map);
    const routeEndLayer = new L.FeatureGroup().addTo(map);
    const drawn = new L.FeatureGroup().addTo(map);

    mapInstanceRef.current = map;
    overlayRef.current = overlay;
    clusterLayerRef.current = clusterLayer;
    pinLayerRef.current = pinLayer;
    routeEndLayerRef.current = routeEndLayer;
    drawnRef.current = drawn;

    let moveTimer = 0;
    const applyViewKey = () => {
      const z = map.getZoom?.() ?? 0;
      const b = map.getBounds?.();
      setMapViewKey(b ? `${z.toFixed(2)}|${boundsToBbox(b)}` : String(z));
    };
    const onMove = () => {
      window.clearTimeout(moveTimer);
      moveTimer = window.setTimeout(() => {
        void loadViewportRef.current();
      }, VIEWPORT_IDLE_MS);
    };
    const onZoomStart = () => {
      paintTokenRef.current += 1;
      setOverlayStatus('tim đường…');
    };
    const onMoveEnd = () => {
      applyViewKey();
      onMove();
    };
    const onZoomEnd = () => {
      ensureLinePanes(map);
    };
    map.on('zoomstart', onZoomStart);
    map.on('moveend', onMoveEnd);
    map.on('zoomend', onZoomEnd);
    void loadViewportRef.current();

    return () => {
      window.clearTimeout(moveTimer);
      viewportAbortRef.current?.abort();
      try {
        map.off?.('moveend', onMoveEnd);
        map.off?.('zoomend', onZoomEnd);
        map.off?.('zoomstart', onZoomStart);
        map.remove();
      } catch {
        /* already gone */
      }
      mapInstanceRef.current = null;
      overlayRef.current = null;
      clusterLayerRef.current = null;
      pinLayerRef.current = null;
      routeEndLayerRef.current = null;
      drawnRef.current = null;
      clipLayerRef.current = null;
      myLocationHoldRef.current.group = null;
      pinByIdRef.current.clear();
      clusterByIdRef.current.clear();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- init once when Leaflet ready
  }, [ready]);

  useEffect(() => {
    if (!ready || !mapInstanceRef.current) return undefined;
    const t = window.setTimeout(() => {
      void loadSavedOntoMap().catch((err: unknown) => {
        setOverlayStatus(err instanceof Error ? err.message : 'Không vẽ được lớp bản đồ');
      });
    }, 0);
    return () => window.clearTimeout(t);
  }, [ready, loadSavedOntoMap]);

  useEffect(() => {
    let cancelled = false;
    const bootstrap = async () => {
      try {
        const [layerRowsApi, drawings, summaryRaw] = await Promise.all([
          gisService.getLayers('live').catch(() => []),
          gisService.listDrawings().catch(() => []),
          gisService.getSummaryByType().catch(() => null),
        ]);
        if (cancelled) return;
        const nextCatalog = layersFromApi(layerRowsApi || [], []);
        setCatalog(nextCatalog);
        if (summaryRaw) {
          const parsed = normalizeTypeSummary(summaryRaw);
          typePlanCacheRef.current.summary = parsed.items;
          setTypeSummary(parsed.items);
          setTypeCatalogReady(true);
        }
        setLayersVisible((prev) => {
          const next = { ...prev };
          nextCatalog.forEach((l) => {
            if (next[l.code] === undefined) next[l.code] = false;
          });
          layersVisibleRef.current = next;
          return next;
        });
        const fromDraw = (drawings || []).map(drawingToSaved);
        setSaved((prev) => {
          const db = prev.filter(isDbInventoryItem);
          const overlay = fromDraw.length
            ? fromDraw
            : prev.filter((s) => !isDbInventoryItem(s));
          return [...overlay, ...db];
        });
        setApiMode('bff');
        setMsg(
          fromDraw.length
            ? `API sẵn sàng · ${fromDraw.length} bản vẽ (chỉ xem) · tải theo viewport`
            : 'API sẵn sàng — tải theo viewport (cụm / tuyến / chi tiết)',
        );
        if (mapInstanceRef.current) void loadViewportRef.current();
      } catch {
        if (!cancelled) {
          setApiMode('local-seed');
          setMsg('BFF/API chưa sẵn — fallback localStorage');
        }
      }
    };
    void bootstrap();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    setLayersVisible((prev) => {
      const next = { ...prev };
      let changed = false;
      for (const row of layerRows) {
        if (next[row.code] === undefined) {
          next[row.code] = false;
          changed = true;
        }
      }
      if (!changed) return prev;
      layersVisibleRef.current = next;
      return next;
    });
  }, [layerRows]);

  useEffect(() => {
    if (!layerRows.length || !typeQuery.length) return undefined;
    const key = typeQuery.join(',');
    const already = appliedTypeKeyRef.current === key;
    const missing = layerRows.some(
      (row) => layerMatchesTypeQuery(row, typeQuery) && layersVisibleRef.current[row.code] !== true,
    );
    if (already && !missing) return undefined;
    const timer = window.setTimeout(() => {
      setLayersVisible((prev) => {
        const next = { ...prev };
        let changed = false;
        const names: string[] = [];
        for (const row of layerRows) {
          if (!layerMatchesTypeQuery(row, typeQuery)) continue;
          if (next[row.code] !== true) {
            next[row.code] = true;
            changed = true;
          }
          names.push(row.name);
        }
        if (!names.length) return prev;
        if (!changed && already) return prev;
        layersVisibleRef.current = next;
        appliedTypeKeyRef.current = key;
        setOverlayStatus(`Lớp ${names.join(', ')} (type=${key})`);
        return next;
      });
      if (mapInstanceRef.current) void loadViewportRef.current();
    }, 0);
    return () => window.clearTimeout(timer);
  }, [layerRows, typeQuery]);

  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!map) return;
    const run = () => syncVnClipGl(map, clipLayerRef.current);
    const t1 = window.setTimeout(run, 50);
    const t2 = window.setTimeout(run, 200);
    return () => {
      window.clearTimeout(t1);
      window.clearTimeout(t2);
    };
  }, [viewFull, sideBodyOpen, stacked]);

  const locateMe = useCallback(() => {
    const map = mapInstanceRef.current;
    const Lf = window.L;
    if (!map || !Lf) return;
    setLocating(true);
    setOverlayStatus('Đang lấy vị trí…');
    void locateUserOnMap(map, Lf, myLocationHoldRef.current)
      .catch((err: unknown) => {
        setOverlayStatus(err instanceof Error ? err.message : 'Không lấy được vị trí');
      })
      .finally(() => setLocating(false));
  }, []);

  const inspectModel = selectedItem
    ? buildGisInspectModel(selectedItem, { snapped: inspectSnapped })
    : null;

  return (
    <div
      className={`${styles.page} ${viewFull ? styles.full : styles.dock}`}
      data-testid="rmms-gis-draw-live-page"
      data-gis-map-page
      data-source-kind="real-seed"
    >
      <div className={styles.app} data-gis-map-app>
        <aside
          className={`${styles.side} ${styles.dockOnly}`}
          data-gis-map-side
          data-collapsed={stacked && !sideBodyOpen ? 'true' : 'false'}
        >
          <GisMapSideTabs
            active={sideTab}
            onSelect={onTabClick}
            stacked={stacked}
            bodyOpen={sideBodyOpen}
            onToggleBody={toggleBody}
            tabClassName={styles.sideTabs}
            tabOnClassName={styles.tabOn}
          />
          <div
            className={styles.sideBody}
            data-gis-map-side-body
            hidden={stacked && !sideBodyOpen}
          >
            {sideTab === 'layers' && (
              <>
                <strong>Loại tài sản</strong>
                {!typeCatalogReady
                  ? Array.from({ length: LAYER_SKELETON_COUNT }, (_, i) => (
                      <div
                        key={`layer-sk-${i}`}
                        className={styles.layerSkeleton}
                        aria-hidden={i > 0}
                        aria-busy={i === 0 ? true : undefined}
                        aria-label={i === 0 ? 'Đang tải loại tài sản' : undefined}
                      >
                        <span className={styles.layerSkeletonIcon} />
                        <span className={styles.layerSkeletonText} />
                      </div>
                    ))
                  : layerRows.map((l) => (
                  <label
                    key={l.code}
                    className={styles.layerItem}
                  >
                    <input
                      type="checkbox"
                      checked={layersVisible[l.code] === true}
                      onChange={(e) => {
                        const checked = e.target.checked;
                        const next = { ...layersVisibleRef.current, [l.code]: checked };
                        layersVisibleRef.current = next;
                        setLayersVisible(next);
                        if (!checked && isolatedLayerRef.current === l.code) {
                          isolatedLayerRef.current = null;
                          setIsolatedLayer(null);
                        }
                        if (mapInstanceRef.current) void loadViewportRef.current();
                      }}
                    />
                    <span
                      dangerouslySetInnerHTML={{
                        __html: assetIconHtml(l.assetCode),
                      }}
                    />
                    {l.name}
                    {fetchingLayers.has(l.code) ? (
                      <span className={styles.layerSpin} aria-hidden />
                    ) : null}
                    <span className={styles.layerCount}>
                      {l.count == null ? '' : formatAssetCount(l.count)}
                    </span>
                  </label>
                ))}
              </>
            )}
            {sideTab === 'legend' && (
              <>
                <strong>Tài sản · QCVN 41</strong>
                {(typeSummary.length ? typeSummary : []).map((t) => (
                  <div key={`leg-${t.type}`} className={styles.legendRow}>
                    <span
                      dangerouslySetInnerHTML={{
                        __html: assetIconHtml(
                          t.assetCode && t.assetCode !== 'TS'
                            ? t.assetCode
                            : assetCodeForType(t.type),
                        ),
                      }}
                    />
                    <span>
                      {gisTypeLabel(t.type)}{' '}
                      <small>
                        {formatAssetCount(t.count)} · {t.mode === 'full' ? 'đủ' : 'vùng'}
                      </small>
                    </span>
                  </div>
                ))}
                {!typeSummary.length
                  ? typeCatalogReady
                    ? layerRows.map((l) => (
                      <div key={`leg-${l.code}`} className={styles.legendRow}>
                        <span
                          dangerouslySetInnerHTML={{
                            __html: assetIconHtml(l.assetCode),
                          }}
                        />
                        <span>{l.name}</span>
                      </div>
                    ))
                    : Array.from({ length: LAYER_SKELETON_COUNT }, (_, i) => (
                      <div key={`leg-sk-${i}`} className={styles.layerSkeleton} aria-hidden>
                        <span className={styles.layerSkeletonIcon} />
                        <span className={styles.layerSkeletonText} />
                      </div>
                    ))
                  : null}
                <div className={styles.legendRow}>
                  <span className={styles.routeSwatch} /> Tuyến · LineString đủ
                </div>
              </>
            )}
            {sideTab === 'props' && (
              <GisAssetInspectPanel
                model={inspectModel}
                loading={inspectLoading}
                className={styles.inspect}
              />
            )}
            {sideTab === 'results' && (
              <div className={styles.list}>
                <strong>
                  {saved.filter((s) => s.layerCode === 'cot-km').length} cột km · tổng {saved.length}
                </strong>
                <ul>
                  {saved.length ? (
                    saved
                      .slice()
                      .reverse()
                      .slice(0, 20)
                      .map((s) => (
                        <li key={s.id}>
                          <button
                            type="button"
                            className={styles.resultBtn}
                            onClick={() => {
                              setIsolatedId(s.id);
                              setIsolatedLayer(s.layerCode);
                              inspectItemRef.current(s);
                              const map = mapInstanceRef.current;
                              if (map) {
                                void fitIsolateSelection(map, {
                                  isolatedId: s.id,
                                  tracks: isolateTracks,
                                  overviewPath: geometryToPath(s.geometry),
                                  delayMs: 40,
                                });
                              }
                            }}
                          >
                            <strong>{s.code}</strong> — {s.name} · {s.layerCode}
                          </button>
                        </li>
                      ))
                  ) : (
                    <li>Chưa có</li>
                  )}
                </ul>
              </div>
            )}
          </div>
        </aside>

        <main className={styles.main} data-gis-map-main>
          <div className={`${styles.statusRow} ${styles.dockOnly}`}>
            <span>EPSG:4326</span>
            <input readOnly value={overlayStatus} aria-label="Overlay status" />
          </div>

          <div className={styles.mapShell}>
            <div className={styles.mapHost}>
              {!ready && !leafletError && (
                <div className={styles.mapLoading}>Đang tải Leaflet…</div>
              )}
              {leafletError && <div className={styles.mapError}>{leafletError}</div>}
              <div
                ref={mapRef}
                className={styles.mapEl}
                role="application"
                aria-label="Bản đồ tài sản"
              />
            </div>
            <div className={styles.mapBar} role="toolbar" aria-label="Lớp nền bản đồ">
              <div className={styles.mapBasemaps} role="group" aria-label="Basemap">
                {CLIP_STYLE_OPTIONS.map((opt) => (
                  <button
                    key={opt.id}
                    type="button"
                    className={clipStyle === opt.id ? styles.isActive : undefined}
                    data-basemap={opt.id}
                    title={opt.title}
                    aria-label={opt.title}
                    aria-pressed={clipStyle === opt.id}
                    onClick={() => {
                      setClipStyle(opt.id);
                      if (clipLayerRef.current) {
                        applyClipBasemapStyle(clipLayerRef.current, opt.id);
                      }
                    }}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              <button
                type="button"
                className={styles.fitBtn}
                data-action="locate-me"
                title={MY_LOCATION_TITLE}
                aria-label={MY_LOCATION_TITLE}
                aria-busy={locating}
                disabled={locating}
                onClick={locateMe}
              >
                {MY_LOCATION_LABEL}
              </button>
              <button
                type="button"
                className={styles.btnMapView}
                data-action="map-view-toggle"
                title={viewFull ? 'Thu về dock (mini)' : 'Phóng full map'}
                aria-label={viewFull ? 'Thu về dock' : 'Phóng full map'}
                aria-pressed={viewFull}
                onClick={() => setViewFull((v) => !v)}
              >
                <MapViewToggleIcon expanded={viewFull} className={styles.mapViewIco} />
              </button>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default GisDrawLivePage;
