import { DETAIL_ZOOM } from './gisMapTypePlan';

export type MapLod = 'cluster' | 'corridor' | 'detail';

export const LOD_CLUSTER_MAX = 8;
export const LOD_CORRIDOR_MAX = 13;
/** One-shot GetCorridors — cấm loadGeoJsonBatched 20 trang. */
export const CORRIDOR_ROUTE_TAKE = 400;
/** Public OSRM: chỉ route nét cắt viewport — cấm 400 tuyến cả nước. */
export const OSRM_VIEWPORT_MAX = 24;
/** z≤8: paint từ index đã ghim, không live OSRM. */
export const OSRM_OVERVIEW_MAX = 36;
export { DETAIL_ZOOM } from './gisMapTypePlan';

/** Wait until pan/zoom idle before loading overlay. */
export const VIEWPORT_IDLE_MS = 220;
/** Same zoom band + bbox overlap → skip cluster refetch (not for detail pins). */
export const VIEWPORT_OVERLAP_SKIP = 0.72;
/** Pad detail bbox so small pans still have pins (do not skip on ~4 km tiles). */
export const VIEWPORT_PAD_RATIO = 0.35;
/** Dump GPS lưới ~0.01° (~1 km) — pad nhỏ hơn lưới → getGeoJson miss pin khi zoom sát. */
export const DETAIL_BBOX_MIN_PAD = 0.02;
/** Cull pin theo dump hoặc điểm đã snap — không dùng 0.002° (viewport z16–18). */
export const DETAIL_PIN_PAD_DEG = 0.015;

/**
 * Viewport: loại lớn cụm → pin khi zoom gần.
 * z≤8: tuyến = nét đã index (show/hide), cấm live OSRM cả nước.
 * z≥9: OSRM miss trong viewport (cap OSRM_VIEWPORT_MAX) rồi ghi index.
 */
export function lodFromZoom(zoom: number | undefined): MapLod {
  const z = zoom ?? 6;
  if (z >= DETAIL_ZOOM) return 'detail';
  if (z <= LOD_CLUSTER_MAX) return 'cluster';
  return 'corridor';
}

export function parseBbox(bbox: string): {
  west: number;
  south: number;
  east: number;
  north: number;
} | null {
  const p = String(bbox || '')
    .split(',')
    .map((x) => Number(x.trim()));
  if (p.length < 4 || p.some((n) => !Number.isFinite(n))) return null;
  return { west: p[0], south: p[1], east: p[2], north: p[3] };
}

export function bboxOverlapRatio(a: string, b: string): number {
  const aa = parseBbox(a);
  const bb = parseBbox(b);
  if (!aa || !bb) return 0;
  const ix = Math.max(0, Math.min(aa.east, bb.east) - Math.max(aa.west, bb.west));
  const iy = Math.max(0, Math.min(aa.north, bb.north) - Math.max(aa.south, bb.south));
  const inter = ix * iy;
  const areaA = Math.max(1e-12, (aa.east - aa.west) * (aa.north - aa.south));
  const areaB = Math.max(1e-12, (bb.east - bb.west) * (bb.north - bb.south));
  return inter / Math.min(areaA, areaB);
}

export function clusterScale(zoom: number | undefined): number {
  const z = zoom ?? 6;
  if (z <= 11) return 2;
  if (z <= 13) return 4;
  return 8;
}

/** Slippy cell by zoom band — refetch when cell, LOD, or cluster grid changes. */
export function viewportTileKey(zoom: number, bbox: string, lod: MapLod): string {
  const box = parseBbox(bbox);
  const span = lod === 'detail' ? 0.04 : lod === 'corridor' ? 0.2 : 0.8;
  if (!box) return `${lod}|na`;
  const cx = (box.west + box.east) / 2;
  const cy = (box.south + box.north) / 2;
  return `${lod}|${clusterScale(zoom)}|${Math.floor(cx / span)}|${Math.floor(cy / span)}`;
}

/** True when inner sits fully inside outer — zoom-in / pan inside loaded area. */
export function bboxCovers(outer: string, inner: string): boolean {
  const o = parseBbox(outer);
  const i = parseBbox(inner);
  if (!o || !i) return false;
  return i.west >= o.west && i.east <= o.east && i.south >= o.south && i.north <= o.north;
}

/** Expand bbox so the fetched region is larger than the viewport. */
export function padBbox(
  bbox: string,
  ratio = VIEWPORT_PAD_RATIO,
  minPad = 0.002,
): string {
  const b = parseBbox(bbox);
  if (!b) return bbox;
  const dx = Math.max(minPad, (b.east - b.west) * ratio);
  const dy = Math.max(minPad, (b.north - b.south) * ratio);
  return `${(b.west - dx).toFixed(4)},${(b.south - dy).toFixed(4)},${(b.east + dx).toFixed(4)},${(b.north + dy).toFixed(4)}`;
}

/** Detail pins: refetch when LOD changes or the view leaves the loaded bbox — do not skip on tile key. */
export function shouldReloadDetail(args: {
  lastLod: MapLod | string;
  lastLoadedBbox: string;
  viewBbox: string;
}): boolean {
  if (args.lastLod !== 'detail') return true;
  if (!args.lastLoadedBbox) return true;
  return !bboxCovers(args.lastLoadedBbox, args.viewBbox);
}

export function latLngInPaddedBounds(
  lat: number,
  lng: number,
  b: { getWest(): number; getSouth(): number; getEast(): number; getNorth(): number },
  padRatio = 0.15,
  minPad = 0.002,
): boolean {
  const w = b.getWest();
  const e = b.getEast();
  const s = b.getSouth();
  const n = b.getNorth();
  const dx = Math.max(minPad, (e - w) * padRatio);
  const dy = Math.max(minPad, (n - s) * padRatio);
  return lng >= w - dx && lng <= e + dx && lat >= s - dy && lat <= n + dy;
}

export function boundsToBbox(b: {
  getWest(): number;
  getSouth(): number;
  getEast(): number;
  getNorth(): number;
}): string {
  return `${b.getWest().toFixed(4)},${b.getSouth().toFixed(4)},${b.getEast().toFixed(4)},${b.getNorth().toFixed(4)}`;
}

export {
  clusterIconSize,
  formatClusterCount as formatAssetCount,
} from '../../shared/map/mapAssetIcons';

/**
 * Overview (z≤8): one bubble / lat×lng grid cell.
 * Marker = a real point in the group (GeoJSON Point), then snap to road centerline — not cell center / centroid.
 * Click cụm / pin: popup only — cấm setView / fitBounds auto zoom.
 */

export function clusterCellBounds(props: Record<string, unknown> | null | undefined): {
  south: number;
  west: number;
  north: number;
  east: number;
} | null {
  if (!props) return null;
  const south = Number(props.south);
  const west = Number(props.west);
  const north = Number(props.north);
  const east = Number(props.east);
  if (![south, west, north, east].every(Number.isFinite)) return null;
  return { south, west, north, east };
}
