import {
  buildCotKmSeedItems,
  QL22_CENTER,
  cotKmBoundsLatLng,
  COT_KM_META,
  type GisSavedItem,
} from './cotKmQl22Seed';

export { QL22_CENTER, cotKmBoundsLatLng, COT_KM_META, buildCotKmSeedItems };

/** Fit toàn quốc khi overlay gov-vn (không kẹp QL.22). */
export const VN_CENTER: [number, number] = [16.15, 106.2];
export const VN_ZOOM = 6;

export interface GisLayerDef {
  code: string;
  name: string;
  geom: 'Point' | 'LineString' | 'Polygon';
}

export const LAYERS: GisLayerDef[] = [
  { code: 'tuyen-duong', name: 'Tuyến đường', geom: 'LineString' },
  { code: 'cot-km', name: 'Cột km', geom: 'Point' },
  { code: 'bien-bao', name: 'Biển báo', geom: 'Point' },
  { code: 'cau', name: 'Cầu', geom: 'Polygon' },
  { code: 'ham', name: 'Hầm', geom: 'Point' },
  { code: 'ho-lan', name: 'Hộ lan', geom: 'LineString' },
  { code: 'cong', name: 'Cống', geom: 'Point' },
  { code: 'ta-luy', name: 'Ta luy / tường chắn', geom: 'Polygon' },
  { code: 'mat-duong', name: 'Đoạn mặt đường', geom: 'LineString' },
];

export const STORAGE_ITEMS = 'rmms-gis-live';
export const STORAGE_FC = 'rmms-gis-live-fc';

export function layerLabel(code: string): string {
  const layer = LAYERS.find((x) => x.code === code);
  return layer ? `${layer.name} (${layer.code})` : code;
}

export function loadSaved(): GisSavedItem[] {
  try {
    const raw = localStorage.getItem(STORAGE_ITEMS);
    if (raw) {
      const parsed = JSON.parse(raw) as GisSavedItem[];
      if (Array.isArray(parsed) && parsed.length) return parsed;
    }
  } catch {
    /* ignore */
  }
  return [];
}

export function persistSaved(items: GisSavedItem[]): void {
  localStorage.setItem(STORAGE_ITEMS, JSON.stringify(items));
  localStorage.setItem(
    STORAGE_FC,
    JSON.stringify({
      type: 'FeatureCollection',
      features: items.map((s) => ({
        type: 'Feature',
        properties: {
          code: s.code,
          name: s.name,
          layerCode: s.layerCode,
          ...(s.props || {}),
        },
        geometry: s.geometry,
      })),
    }),
  );
}

export function loadFeatureCollection(): GeoJSON.FeatureCollection | null {
  try {
    const raw = localStorage.getItem(STORAGE_FC);
    return raw ? (JSON.parse(raw) as GeoJSON.FeatureCollection) : null;
  } catch {
    return null;
  }
}

export function clearSaved(): void {
  localStorage.removeItem(STORAGE_ITEMS);
  localStorage.removeItem(STORAGE_FC);
}

export function resetToCotKmSeed(): GisSavedItem[] {
  clearSaved();
  const seed = buildCotKmSeedItems();
  persistSaved(seed);
  return seed;
}
