const DELINEATOR_TIEU = [
  'guide_post_type_id',
  'average_installation_interval',
  'length',
  'width',
  'height',
  'total_number_within_section',
];

const DELINEATOR_H = [
  'h_post_type_id',
  'h_guide_post_type_id',
  'h_average_installation_interval',
  'h_length',
  'h_width',
  'h_height',
  'h_total_number_within_section',
];

const DELINEATOR_POS = [
  'installed_location_id',
  'from_coordinatex',
  'from_coordinatey',
  'to_coordinatex',
  'to_coordinatey',
  'province_from_id',
  'town_from_id',
  'province_to_id',
  'town_to_id',
];

export function dumpSpecLabel(key: string): string {
  const k = key.trim().toLowerCase();
  return DUMP_SPEC_LABELS[k] ?? DUMP_SPEC_LABELS[k.replace(/_/g, '-')] ?? key.replace(/_/g, ' ');
}

export function parseDumpSpecs(raw: string | null | undefined): DumpSpecRow[] {
  if (!raw || !raw.trim()) return [];
  try {
    const obj = JSON.parse(raw) as Record<string, unknown>;
    return Object.entries(obj)
      .filter(([, v]) => v != null && String(v).trim() !== '')
      .map(([key, v]) => ({
        key,
        label: dumpSpecLabel(key),
        value: String(v),
      }));
  } catch {
    return [];
  }
}

export function getDumpSpecValue(
  raw: string | null | undefined,
  key: string,
): string {
  const want = key.trim().toLowerCase();
  const hit = parseDumpSpecs(raw).find((r) => r.key.toLowerCase() === want);
  return hit?.value ?? '';
}

/** Merge patch into dumpSpecs JSON; empty/null removes key. */
export function mergeDumpSpecs(
  raw: string | null | undefined,
  patch: Record<string, string | null | undefined>,
): string {
  let obj: Record<string, unknown> = {};
  if (raw && raw.trim()) {
    try {
      const parsed = JSON.parse(raw) as Record<string, unknown>;
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        obj = { ...parsed };
      }
    } catch {
      obj = {};
    }
  }
  for (const [k, v] of Object.entries(patch)) {
    if (v == null || String(v).trim() === '') {
      delete obj[k];
    } else {
      obj[k] = String(v).trim();
    }
  }
  return Object.keys(obj).length ? JSON.stringify(obj) : '';
}

function takeKeys(byKey: Map<string, DumpSpecRow>, keys: string[]): DumpSpecRow[] {
  return keys.map((k) => byKey.get(k)).filter((r): r is DumpSpecRow => r != null);
}

/** Nhóm hộ chiếu theo loại — cọc tiêu / cọc H tách 2 bộ đúng dump. */
export function groupDumpSpecs(type: string, rows: DumpSpecRow[]): DumpSpecGroup[] {
  if (!rows.length) return [];
  if (type !== 'DELINEATOR') {
    return [{ title: 'Thông số theo loại', rows }];
  }
  const byKey = new Map(rows.map((r) => [r.key.toLowerCase(), r]));
  const used = new Set([...DELINEATOR_TIEU, ...DELINEATOR_H, ...DELINEATOR_POS]);
  const groups: DumpSpecGroup[] = [];
  const pos = takeKeys(byKey, DELINEATOR_POS);
  const tieu = takeKeys(byKey, DELINEATOR_TIEU);
  const h = takeKeys(byKey, DELINEATOR_H);
  const rest = rows.filter((r) => !used.has(r.key.toLowerCase()));
  if (pos.length) groups.push({ title: 'Vị trí (dump)', rows: pos });
  if (tieu.length) groups.push({ title: 'Cọc tiêu', rows: tieu });
  if (h.length) groups.push({ title: 'Cọc H / cột H', rows: h });
  if (rest.length) groups.push({ title: 'Thông số khác', rows: rest });
  return groups;
}
