import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';
import type { GisSavedItem } from '../../demo/cotKmQl22Seed';

/** GET existing Asset BFF — cấm invent API (GOV-IMP). */
const BASE = '/asset/road-assets';

const GUID =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export type RoadAssetDetailDto = {
  id: string;
  code: string;
  name: string;
  type: string;
  route: string;
  routeName?: string;
  routeNamed?: string;
  routeNamedName?: string;
  routeSegment?: string;
  routeSegmentName?: string;
  dumpSpecs?: string;
  kmFrom: string;
  kmTo?: string;
  status: string;
  lat?: number | null;
  lng?: number | null;
  quantity?: number | null;
  unitCode?: string;
  note?: string;
};

export function isRoadAssetGuid(id: string): boolean {
  return GUID.test(String(id || '').trim());
}

export async function getRoadAssetDetail(id: string): Promise<RoadAssetDetailDto> {
  const res = await apiClient.get<BffResponse<RoadAssetDetailDto>>(`${BASE}/${id}`);
  return unwrap(res);
}

export function mergeRoadAssetDetail(
  item: GisSavedItem,
  dto: RoadAssetDetailDto,
): GisSavedItem {
  return {
    ...item,
    code: dto.code || item.code,
    name: dto.name || item.name,
    props: {
      ...item.props,
      type: dto.type || item.props?.type,
      route: dto.route || item.props?.route,
      routeName: dto.routeName,
      routeNamed: dto.routeNamed,
      routeNamedName: dto.routeNamedName,
      routeSegment: dto.routeSegment,
      routeSegmentName: dto.routeSegmentName,
      kmFrom: dto.kmFrom || item.props?.kmFrom,
      kmTo: dto.kmTo,
      dumpSpecs: dto.dumpSpecs,
      status: dto.status || item.props?.status,
      quantity: dto.quantity,
      unitCode: dto.unitCode,
      note: dto.note ?? item.props?.note,
    },
  };
}
