/** Paint plan: tuyến = LineString đủ; loại < 100 = pin đủ; loại ≥ 100 = cụm theo vùng viewport. */

export const FULL_SHOW_MAX = 100;
export const DETAIL_ZOOM = 14;
/** Ngân sách pin DOM trong 1 viewport (z≥14). */
export const DETAIL_PIN_BUDGET = 800;
export const DETAIL_PAGE = 150;
export const DETAIL_TYPE_PRIORITY = [
  'KM_POST',
  'TRAFFIC_SIGN',
  'BRIDGE',
  'TUNNEL',
  'CONVEX_MIRROR',
  'CULVERT_X',
  'CULVERT_L',
  'GUARDRAIL',
];

export type GisTypePaintMode = 'full' | 'cluster';

export type GisTypeSummaryItem = {
  type: string;
  layerCode: string;
  assetCode: string;
  count: number;
  mode: GisTypePaintMode;
};

export type GisTypeSummaryResult = {
  items: GisTypeSummaryItem[];
  totalCount: number;
  fullThreshold: number;
};

export function isDetailZoom(zoom: number | undefined): boolean {
  return (zoom ?? 6) >= DETAIL_ZOOM;
}

export function normalizeTypeSummary(raw: unknown): GisTypeSummaryResult {
  const src = (raw || {}) as Record<string, unknown>;
  const rows = Array.isArray(src.items) ? src.items : [];
  const items: GisTypeSummaryItem[] = rows.map((row) => {
    const r = (row || {}) as Record<string, unknown>;
    const count = Number(r.count) || 0;
    const mode: GisTypePaintMode =
      String(r.mode || '').toLowerCase() === 'full' || count < FULL_SHOW_MAX
        ? 'full'
        : 'cluster';
    return {
      type: String(r.type || ''),
      layerCode: String(r.layerCode || ''),
      assetCode: String(r.assetCode || 'TS'),
      count,
      mode,
    };
  }).filter((x) => x.type);
  return {
    items,
    totalCount: Number(src.totalCount) || items.reduce((n, x) => n + x.count, 0),
    fullThreshold: Number(src.fullThreshold) || FULL_SHOW_MAX,
  };
}

export function typesForMode(
  items: GisTypeSummaryItem[],
  mode: GisTypePaintMode,
  isolatedLayer?: string | null,
): GisTypeSummaryItem[] {
  return items.filter((x) => {
    if (x.mode !== mode) return false;
    if (
      isolatedLayer
      && isolatedLayer !== x.type
      && isolatedLayer !== x.layerCode
    ) {
      return false;
    }
    return true;
  });
}

export function sortTypesForDetail(items: GisTypeSummaryItem[]): GisTypeSummaryItem[] {
  return items.slice().sort((a, b) => {
    const ia = DETAIL_TYPE_PRIORITY.indexOf(a.type);
    const ib = DETAIL_TYPE_PRIORITY.indexOf(b.type);
    const pa = ia < 0 ? 80 : ia;
    const pb = ib < 0 ? 80 : ib;
    if (pa !== pb) return pa - pb;
    return b.count - a.count;
  });
}

/** Lớp đã tick — default off nên chỉ `true` mới vào set. */
function normTypeToken(raw: string): string {
  return String(raw || '')
    .trim()
    .toUpperCase()
    .replace(/-/g, '_');
}

const ROUTE_TYPE_ALIASES = new Set(['TUYEN_DUONG', 'TUYEN', 'ROUTE', 'TD', 'ROAD']);

/** `?type=BUS_STOP` · comma/`+`/`|` nhiều loại. */
export function parseAssetTypeQuery(search: string): string[] {
  const q = new URLSearchParams(search.startsWith('?') ? search.slice(1) : search);
  const raw = q.get('type') || q.get('types') || '';
  const seen = new Set<string>();
  const out: string[] = [];
  for (const part of raw.split(/[,+|]/)) {
    const t = normTypeToken(part);
    if (!t || seen.has(t)) continue;
    seen.add(t);
    out.push(t);
  }
  return out;
}

export function layerMatchesTypeQuery(
  row: { code: string; drawLayer?: string; assetCode?: string },
  types: string[],
): boolean {
  if (!types.length) return false;
  const code = normTypeToken(row.code);
  const draw = normTypeToken(row.drawLayer || '');
  const asset = normTypeToken(row.assetCode || '');
  const isRouteRow = ROUTE_TYPE_ALIASES.has(code) || draw === 'TUYEN_DUONG';
  for (const t of types) {
    if (t === code || t === draw || t === asset) return true;
    if (ROUTE_TYPE_ALIASES.has(t) && isRouteRow) return true;
  }
  return false;
}

export function selectedLayerSet(layersVisible: Record<string, boolean>): Set<string> {
  return new Set(
    Object.entries(layersVisible)
      .filter(([, on]) => on === true)
      .map(([code]) => code),
  );
}

export function countForLayer(items: GisTypeSummaryItem[], layerCode: string): number {
  return items
    .filter((x) => x.layerCode === layerCode || x.type === layerCode)
    .reduce((n, x) => n + x.count, 0);
}

export function filterSelectedTypes(
  items: GisTypeSummaryItem[],
  selected: Set<string>,
): GisTypeSummaryItem[] {
  if (selected.size === 0) return [];
  return items.filter((x) => selected.has(x.type) || selected.has(x.layerCode));
}

export type AssetTypeRow = {
  code: string;
  name: string;
  geom: 'Point' | 'LineString' | 'Polygon';
  assetCode: string;
  count: number | null;
  drawLayer: string;
};

export const LAYER_SKELETON_COUNT = 5;

export function catalogFromTypeSummary(
  items: GisTypeSummaryItem[],
  assetMetaOf: (code: string) => { label: string; geom?: 'Point' | 'LineString' | 'Polygon' },
  assetCodeOfType: (type: string) => string,
  typeLabelOf: (type: string) => string,
): AssetTypeRow[] {
  const rows: AssetTypeRow[] = [];
  const seen = new Set<string>();
  const sorted = items
    .filter((t) => t.count > 0 && t.type)
    .slice()
    .sort((a, b) => b.count - a.count);
  for (const t of sorted) {
    const type = t.type.trim().toUpperCase();
    if (seen.has(type)) continue;
    seen.add(type);
    const assetCode = (t.assetCode && t.assetCode !== 'TS' ? t.assetCode : assetCodeOfType(type)).toUpperCase();
    const meta = assetMetaOf(assetCode);
    rows.push({
      code: type,
      name: typeLabelOf(type) || meta.label,
      geom: meta.geom || 'Point',
      assetCode,
      count: t.count,
      drawLayer: t.layerCode || type,
    });
  }
  return rows;
}
